import 'package:flutter/foundation.dart';
import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';
import '../../../core/widgets/common.dart';
import '../../viewer/document_bytes.dart';
import '../../viewer/document_flow.dart';
import '../data/pdf_studio_repository.dart';
import '../data/studio_pdf_engine.dart';
import 'scan_page_editor.dart';
import 'page_grid.dart';

Future<void> showCreatePdf(BuildContext context) async {
  final router = GoRouter.of(context);
  final source = await showModalBottomSheet<String>(
    context: context,
    showDragHandle: true,
    builder: (c) => SafeArea(
      child: Padding(
        padding: const EdgeInsets.fromLTRB(16, 0, 16, 16),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text('Create PDF', style: Theme.of(c).textTheme.titleLarge),
            const SizedBox(height: 12),
            ListTile(
              leading: const Icon(Icons.camera_alt_rounded),
              title: const Text('Scan with camera'),
              subtitle: const Text('Capture and add pages'),
              onTap: () => Navigator.pop(c, 'camera'),
            ),
            ListTile(
              leading: const Icon(Icons.photo_library_outlined),
              title: const Text('From gallery images'),
              subtitle: const Text('Select photos, arrange and save'),
              onTap: () => Navigator.pop(c, 'gallery'),
            ),
          ],
        ),
      ),
    ),
  );
  if (source != null) router.push('/create-pdf?source=$source');
}

class ScanPdfScreen extends ConsumerStatefulWidget {
  const ScanPdfScreen({super.key, this.initialAction, this.archiveId});
  final String? initialAction;
  final String? archiveId;
  @override
  ConsumerState<ScanPdfScreen> createState() => _ScanPdfScreenState();
}

class _ScanPdfScreenState extends ConsumerState<ScanPdfScreen>
    with WidgetsBindingObserver {
  static const _camera = MethodChannel('com.hyzen.pharmd/camera_pages');
  final _name = TextEditingController(text: 'Scanned notes');
  List<String> _pages = [];
  bool _busy = true, _selecting = false;
  String? _exportJob;
  bool _cancelPending = false, _exporting = false;
  final Set<int> _selected = {};
  String? _error;
  bool get _android =>
      !kIsWeb && defaultTargetPlatform == TargetPlatform.android;
  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    WidgetsBinding.instance.addPostFrameCallback((_) => _restore());
  }

  Future<void> _restore() async {
    try {
      if (_android) {
        _pages = widget.archiveId == null
            ? await _camera.invokeListMethod<String>('recover') ?? []
            : await _camera.invokeListMethod<String>('openArchive', {'id': widget.archiveId}) ?? [];
      }
    } on PlatformException catch (e) {
      _error = e.message ?? 'Could not restore this scan.';
    } catch (_) {
      _error = 'Could not restore this scan.';
    }
    if (!mounted) return;
    setState(() => _busy = false);
    if (widget.initialAction == 'camera') {
      await _scan();
    } else if (widget.initialAction == 'gallery') {
      await _gallery();
    }
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    _name.dispose();
    super.dispose();
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.resumed && !_busy && _android) {
      _refreshDraft();
    }
  }

  Future<void> _refreshDraft() async {
    try {
      final pages = await _camera.invokeListMethod<String>('recover');
      if (mounted && !_busy && pages != null) setState(() => _pages = pages);
    } catch (_) {}
  }

  Future<void> _work(Future<void> Function() action) async {
    if (_busy) return;
    setState(() {
      _busy = true;
      _error = null;
    });
    try {
      await action();
    } on PlatformException catch (e) {
      if (mounted) {
        setState(
          () => _error =
              e.code == 'export_cancelled' ? 'Export cancelled. Your pages are still here.' : e.message ?? 'Could not prepare this page. Please retry.',
        );
      }
    } catch (_) {
      if (mounted) {
        setState(
          () => _error =
              'Could not finish. Your pages are still here; please retry.',
        );
      }
    } finally {
      if (mounted) setState(() => _busy = false);
    }
  }

  Future<void> _scan() => _work(() async {
    var legacy = false;
    try {
      final result = await const MethodChannel('com.hyzen.pharmd/live_scanner').invokeMapMethod<String, dynamic>('scan');
      if (result != null && mounted) {
        final pages = List<String>.from(result['pages'] as List? ?? []);
        setState(() => _pages = pages);
        if (result['action'] == 'gallery') {
          await _importGallery();
        } else if (result['action'] == 'legacy') {
          legacy = true;
        }
      }
    } on MissingPluginException {
      legacy = true;
    }
    if (!legacy) return;
    try {
      final paths = await const MethodChannel('com.hyzen.pharmd/document_scanner').invokeListMethod<String>('scan');
      if (mounted && paths != null) setState(() => _pages = paths);
    } on MissingPluginException {
      final paths = await _camera.invokeListMethod<String>('capture');
      if (mounted && paths != null) setState(() => _pages = paths);
    }
  });

  Future<void> _editPage(int i) async {
    if (_busy) return;
    final edit = await Navigator.of(context).push<ScanPageEdit>(
      MaterialPageRoute(builder: (_) => ScanPageEditor(path: _pages[i], nativeDraft: _android)),
    );
    if (edit == null || !mounted) return;
    await _work(() async {
      var next = [..._pages];
      if (edit.crop != null) {
        next =
            await _camera.invokeListMethod<String>('edit', {
              'paths': [next[i]],
              'filter': 'original',
              'quad': edit.crop,
            }) ??
            next;
        if (mounted) setState(() => _pages = next);
      }
      {
        next =
            await _camera.invokeListMethod<String>('edit', {
              'paths': edit.all ? next : [next[i]],
              'filter': edit.filter,
              'brightness': edit.brightness, 'contrast': edit.contrast,
            }) ??
            next;
      }
      if (mounted) setState(() => _pages = next);
    });
  }

  Future<void> _history(int index, String action) => _work(() async {
    final paths = await _camera.invokeListMethod<String>(action, {'path': _pages[index]});
    if (mounted && paths != null) setState(() => _pages = paths);
  });

  void _back() {
    if (_busy) return;
    // Draft is durable. Leaving the editor never closes the app or discards it.
    if (context.canPop()) {
      context.pop();
    } else {
      context.go('/pdf-studio');
    }
  }

  Future<void> _capture() => _work(() async {
    final paths = await _camera.invokeListMethod<String>('capture');
    if (mounted && paths != null) setState(() => _pages = paths);
  });
  Future<void> _gallery() => _work(_importGallery);
  Future<void> _importGallery() async {
    final files = await StudioPdfEngine.pickFiles();
    final paths = files
        .where(
          (f) => RegExp(
            r'\.(jpe?g|png|webp)$',
            caseSensitive: false,
          ).hasMatch(f.path),
        )
        .map((f) => f.path)
        .toList();
    if (files.isNotEmpty && paths.isEmpty) {
      throw PlatformException(
        code: 'images',
        message: 'Choose JPG, PNG or WebP images.',
      );
    }
    if (paths.isEmpty) return;
    final next = _android
        ? await _camera.invokeListMethod<String>('addImages', {'paths': paths})
        : [..._pages, ...paths];
    if (mounted && next != null) setState(() => _pages = next);
  }
  Future<void> _replace(List<String> pages) => _work(() async {
    _selected.clear();
    final next = _android
        ? await _camera.invokeListMethod<String>('replace', {'paths': pages})
        : pages;
    if (mounted && next != null) setState(() => _pages = next);
  });
  Future<void> _discard() async {
    final confirmed = await showDialog<bool>(context: context, builder: (c) => AlertDialog(
      title: const Text('Discard current scan?'),
      content: const Text('Current pages and removal history will be deleted. Saved PDFs and saved scans stay available.'),
      actions: [TextButton(onPressed: () => Navigator.pop(c, false), child: const Text('Keep scan')),
        FilledButton(onPressed: () => Navigator.pop(c, true), child: const Text('Discard'))],
    ));
    if (confirmed != true || !mounted) return;
    await _work(() async {
      await _camera.invokeMethod<bool>('clear');
      if (mounted) setState(() { _pages = []; _selected.clear(); _selecting = false; });
    });
  }
  Future<void> _undoRemoval() => _work(() async {
    final next = await _camera.invokeListMethod<String>('undoRemoval');
    if (mounted && next != null) setState(() { _pages = next; _selected.clear(); });
  });
  Future<void> _rotate(String path) => _work(() async {
    final next = await _camera.invokeListMethod<String>('rotate', {
      'path': path,
    });
    if (mounted && next != null) setState(() => _pages = next);
  });
  Future<void> _save() async {
    if (_busy || _pages.isEmpty) return;
    var highQuality = false;
    var paper = 'a4', orientation = 'auto';
    var margin = 16;
    final confirmed = await showModalBottomSheet<bool>(
      context: context, isScrollControlled: true, useSafeArea: true,
      constraints: BoxConstraints(maxHeight: MediaQuery.sizeOf(context).height * .85),
      builder: (sheetContext) => StatefulBuilder(builder: (context, update) => Padding(
        padding: EdgeInsets.fromLTRB(20, 20, 20, 20 + MediaQuery.viewInsetsOf(context).bottom),
        child: SingleChildScrollView(child: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.stretch, children: [
          Text('Export scan', style: Theme.of(context).textTheme.titleLarge),
          const SizedBox(height: 12),
          TextField(controller: _name, maxLength: 100, decoration: const InputDecoration(labelText: 'PDF filename')),
          if (_android) SwitchListTile(contentPadding: EdgeInsets.zero, title: const Text('Higher quality'),
            subtitle: const Text('Up to 2600 px per page. Uses more memory and storage.'), value: highQuality,
            onChanged: (value) => update(() => highQuality = value)),
          DropdownButtonFormField<String>(initialValue: paper, decoration: const InputDecoration(labelText: 'Paper size'), items: const [DropdownMenuItem(value: 'a4', child: Text('A4')), DropdownMenuItem(value: 'letter', child: Text('US Letter')), DropdownMenuItem(value: 'legal', child: Text('US Legal'))], onChanged: (v) => update(() => paper = v!)),
          const SizedBox(height: 12),
          DropdownButtonFormField<String>(initialValue: orientation, decoration: const InputDecoration(labelText: 'Orientation'), items: const [DropdownMenuItem(value: 'auto', child: Text('Match each page')), DropdownMenuItem(value: 'portrait', child: Text('Portrait')), DropdownMenuItem(value: 'landscape', child: Text('Landscape'))], onChanged: (v) => update(() => orientation = v!)),
          SwitchListTile(contentPadding: EdgeInsets.zero, title: const Text('Page margins'), subtitle: const Text('Fit the whole image without cutting off edges.'), value: margin > 0, onChanged: (v) => update(() => margin = v ? 16 : 0)),
          const Text('Saved to your app workspace with editable originals.'),
          const SizedBox(height: 16),
          FilledButton(onPressed: () => Navigator.pop(sheetContext, true), child: const Text('Export PDF')),
        ])),
      )),
    );
    if (confirmed != true || !mounted) return;
    await _export(highQuality, paper, orientation, margin);
  }

  Future<void> _export(bool highQuality, String paper, String orientation, int margin) => _work(() async {
    if (_pages.isEmpty) return;
    String? ticket;
    setState(() { _exporting = true; _cancelPending = false; });
    try {
    if (_android) {
      try { final job = await StudioPdfEngine.beginScanExport(); ticket = job; if (mounted) setState(() => _exportJob = job); }
      on MissingPluginException { /* Older native build: export without a cancellation claim. */ }
    }
    final path = await StudioPdfEngine.imagesToPdf(_pages, scanDraft: _android, highQuality: highQuality, paper: paper, orientation: orientation, margin: margin, exportJob: _exportJob);
    if (mounted) setState(() => _exportJob = null);
    final count = await StudioPdfEngine.pageCount(path);
    if (count != _pages.length) throw const FormatException('Incomplete PDF');
    final name = _name.text.trim().replaceFirst(
      RegExp(r'\.pdf$', caseSensitive: false),
      '',
    );
    final item = await ref
        .read(pdfStudioHistoryProvider.notifier)
        .importFile(
          path,
          originalFileName: '${name.isEmpty ? 'Scanned notes' : name}.pdf',
          sourceType: 'IMAGE_SCAN',
          operationBadge: 'SCANNED',
        );
    await ref
        .read(pdfStudioHistoryProvider.notifier)
        .updatePageCount(item.id, count);
    if (_android) {
      final archived = await _camera.invokeMethod<bool>('archive', {'id': item.id, if (ticket != null) 'exportJob': ticket});
      if (archived != true) throw const FormatException('PDF saved, but editable scan backup failed. Draft retained.');
      await _camera.invokeMethod<bool>('clear', {if (ticket != null) 'exportJob': ticket});
    }
    if (mounted) {
      showHSnack(context, 'PDF saved to your workspace');
      context.replace('/pdf-studio/saved/${item.id}');
    }
    } finally {
      if (ticket != null) { try { await StudioPdfEngine.finishScanExport(ticket); } catch (_) { /* Native owner teardown/expiry recovers abandoned preparation. */ } }
      if (mounted) setState(() { _exportJob = null; _exporting = false; _cancelPending = false; }); }
  });
  Future<void> _cancelExport() async {
    final id = _exportJob;
    if (id == null || _cancelPending) return;
    setState(() => _cancelPending = true);
    try {
      final accepted = await StudioPdfEngine.cancelScanExport(id);
      if (mounted && !accepted) setState(() { _exportJob = null; _cancelPending = false; });
    } catch (_) {
      if (mounted) { setState(() => _cancelPending = false); showHSnack(context, 'Could not request cancellation. Export is still running.', error: true); }
    }
  }
  @override
  Widget build(BuildContext context) {
    ref.listen(documentDraftRevisionProvider, (_, __) {
      if (!_busy) _refreshDraft();
    });
    final t = Theme.of(context);
    return PopScope(
      canPop: false,
      onPopInvokedWithResult: (didPop, _) {
        if (!didPop) _back();
      },
      child: Scaffold(
        appBar: HTopBar(
          title: 'Create PDF',
          subtitle: '${_pages.length} pages',
          onBack: _back,
        ),
        body: Column(
          children: [
            if (_busy) const LinearProgressIndicator(minHeight: 2),
            if (_exporting) Padding(padding: const EdgeInsets.symmetric(horizontal: 16), child: Row(children: [
              Expanded(child: Text(_cancelPending ? 'Stopping export…' : _exportJob != null ? 'Preparing PDF…' : 'Finishing save…')),
              if (_exportJob != null) TextButton(onPressed: _cancelPending ? null : _cancelExport, child: const Text('Cancel export')),
            ])),
            if (_error != null)
              Padding(
                padding: const EdgeInsets.all(12),
                child: Text(
                  _error!,
                  style: TextStyle(color: t.colorScheme.error),
                ),
              ),
            if (_error != null && _android)
              TextButton.icon(
                onPressed: _busy ? null : _capture,
                icon: const Icon(Icons.camera_alt_outlined),
                label: const Text('Use basic camera'),
              ),
            Padding(
              padding: const EdgeInsets.fromLTRB(16, 10, 16, 8),
              child: TextField(
                controller: _name,
                maxLength: 100,
                decoration: const InputDecoration(
                  labelText: 'PDF name',
                  isDense: true,
                  counterText: '',
                ),
              ),
            ),
            Padding(padding: const EdgeInsets.symmetric(horizontal: 16), child: Wrap(
              spacing: 8, crossAxisAlignment: WrapCrossAlignment.center, children: [
                FilterChip(label: const Text('Select pages'), selected: _selecting,
                  onSelected: _busy ? null : (v) => setState(() { _selecting = v; _selected.clear(); })),
                if (_selecting) ...[
                  TextButton(onPressed: _busy ? null : () => setState(() { _selected.clear(); _selected.addAll(List.generate(_pages.length, (i) => i)); }), child: const Text('Select all')),
                  TextButton.icon(onPressed: _busy || _selected.isEmpty ? null : () => _replace([for(var i=0;i<_pages.length;i++) if(!_selected.contains(i)) _pages[i]]), icon: const Icon(Icons.delete_outline), label: Text('Remove ${_selected.length}')),
                ],
                if (_android) ...[
                  IconButton(tooltip: 'Restore last removed pages', onPressed: _busy ? null : _undoRemoval, icon: const Icon(Icons.restore_page_outlined)),
                  IconButton(tooltip: 'Discard current scan', onPressed: _busy ? null : _discard, icon: const Icon(Icons.delete_sweep_outlined)),
                ],
              ],
            )),
            Expanded(
              child: _pages.isEmpty
                  ? const EmptyState(
                      icon: Icons.document_scanner_outlined,
                      title: 'Add your first page',
                      message: 'Scan a document or choose photos below.',
                    )
                  : PageGrid(
                      count: _pages.length,
                      selected: _selected,
                      onSelect: !_selecting || _busy ? null : (i) => setState(() { if (!_selected.add(i)) _selected.remove(i); }),
                      identity: (i) => _pages[i],
                      image: (i) => ScanPageImage(
                        key: ValueKey(_pages[i]),
                        path: _pages[i],
                      ),
                      onMove: (from, to) {
                        if (_busy) return;
                        final next = [..._pages];
                        next.insert(to, next.removeAt(from));
                        _replace(next);
                      },
                      onEdit: _busy ? null : _editPage,
                      onUndo: _busy || !_android ? null : (i) => _history(i, 'undo'),
                      onReset: _busy || !_android ? null : (i) => _history(i, 'reset'),
                      onRotate: _busy ? null : (i) => _rotate(_pages[i]),
                      onRemove: _busy
                          ? null
                          : (i) => _replace([..._pages]..removeAt(i)),
                    ),
            ),
          ],
        ),
        bottomNavigationBar: SafeArea(
          top: false,
          child: Padding(
            padding: const EdgeInsets.fromLTRB(12, 8, 12, 10),
            child: Row(
              children: [
                if (_android)
                  Expanded(
                    child: OutlinedButton.icon(
                      onPressed: _busy ? null : _scan,
                      icon: const Icon(Icons.add_a_photo_outlined, size: 19),
                      label: const Text('Scan'),
                    ),
                  ),
                const SizedBox(width: 8),
                IconButton(
                  tooltip: 'Choose gallery images',
                  onPressed: _busy ? null : _gallery,
                  icon: const Icon(Icons.photo_library_outlined),
                ),
                const SizedBox(width: 8),
                Expanded(
                  child: FilledButton.icon(
                    onPressed: _busy || _pages.isEmpty ? null : _save,
                    icon: const Icon(Icons.picture_as_pdf_rounded, size: 19),
                    label: const Text('Save PDF'),
                  ),
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }
}

class ScanPageImage extends StatefulWidget {
  const ScanPageImage({super.key, required this.path});
  final String path;
  @override
  State<ScanPageImage> createState() => _ScanPageImageState();
}

class _ScanPageImageState extends State<ScanPageImage> {
  late final Future<Uint8List> _bytes = documentBytes(widget.path);
  @override
  Widget build(BuildContext context) => FutureBuilder<Uint8List>(
    future: _bytes,
    builder: (_, s) => s.hasData
        ? Image.memory(
            s.data!,
            cacheWidth: 180,
            fit: BoxFit.contain,
            errorBuilder: (_, __, ___) => const Icon(Icons.image_outlined),
          )
        : const Icon(Icons.image_outlined),
  );
}

