package com.hyzen.pharmd

import java.nio.ByteBuffer
import kotlin.math.*

/** Bounded luminance-only prototype. No color conversion, network or model download.
 * Conservative segmentation intentionally returns null for ambiguous/background-touching regions. */
object ScanDetector {
    data class Gray(val pixels: ByteArray, val width: Int, val height: Int)
    data class Candidate(val corners: List<Double>, val ratio: Double, val exposure: Double, val sharpness: Double, val fill: Double) {
        val autoEligible get() = exposure in 30.0..250.0 && sharpness >= 90.0 && fill >= .72
    }
    fun sample(buffer: ByteBuffer, rowStride: Int, pixelStride: Int, left: Int, top: Int,
               width: Int, height: Int, rotation: Int, maxEdge: Int = 256): Gray {
        require(width > 0 && height > 0 && rowStride > 0 && pixelStride > 0 && maxEdge in 32..512)
        require(rotation in listOf(0,90,180,270))
        val step = max(1, ceil(max(width,height).toDouble()/maxEdge).toInt())
        val w = (width+step-1)/step; val h=(height+step-1)/step
        val ow=if(rotation%180==0) w else h;val oh=if(rotation%180==0) h else w
        val out=ByteArray(ow*oh);val base=buffer.position()
        for(y in 0 until h) for(x in 0 until w) {
            val index=base+(top+min(y*step,height-1))*rowStride+(left+min(x*step,width-1))*pixelStride
            require(index in base until buffer.limit())
            val dx=when(rotation){90->h-1-y;180->w-1-x;270->y;else->x}
            val dy=when(rotation){90->x;180->h-1-y;270->w-1-x;else->y}
            out[dy*ow+dx]=buffer.get(index)
        }
        return Gray(out,ow,oh)
    }
    private data class P(val x: Int,val y: Int)
    private fun cross(a:P,b:P,c:P)=(b.x-a.x).toLong()*(c.y-a.y)-(b.y-a.y).toLong()*(c.x-a.x)
    private fun quad(points: List<P>): List<P> {
        val sorted=points.distinct().sortedWith(compareBy<P>{it.x}.thenBy{it.y})
        if(sorted.size<4) return emptyList()
        val lower=mutableListOf<P>();val upper=mutableListOf<P>()
        for(p in sorted){while(lower.size>=2 && cross(lower[lower.size-2],lower.last(),p)<=0) lower.removeAt(lower.lastIndex);lower.add(p)}
        for(p in sorted.asReversed()){while(upper.size>=2 && cross(upper[upper.size-2],upper.last(),p)<=0) upper.removeAt(upper.lastIndex);upper.add(p)}
        lower.removeAt(lower.lastIndex);upper.removeAt(upper.lastIndex)
        val hull=(lower+upper).toMutableList()
        while(hull.size>4){
            val i=hull.indices.minByOrNull{abs(cross(hull[(it+hull.size-1)%hull.size],hull[it],hull[(it+1)%hull.size]))}!!
            hull.removeAt(i)
        }
        if(hull.size!=4) return emptyList()
        val start=hull.indices.minByOrNull{hull[it].x+hull[it].y}!!
        return (0..3).map{hull[(start+it)%4]}
    }
    fun detect(gray: Gray): Candidate? {
        val w=gray.width;val h=gray.height;val n=w*h;val data=gray.pixels
        require(w in 8..512 && h in 8..512 && data.size==n)
        val hist=IntArray(256);var sum=0.0;var squares=0.0
        for(v in data){val a=v.toInt() and 255;hist[a]++;sum+=a;squares+=a*a}
        val mean=sum/n
        if(sqrt(max(0.0,squares/n-mean*mean))<18) return null
        var below=0;var belowSum=0.0;var best=-1.0;var threshold=127
        for(t in 0..254){below+=hist[t];belowSum+=hist[t]*t;if(below==0||below==n)continue
            val delta=belowSum/below-(sum-belowSum)/(n-below);val score=below.toDouble()*(n-below)*delta*delta
            if(score>best){best=score;threshold=t}}
        var winner:Candidate?=null;var winnerArea=0.0
        for(bright in listOf(true,false)){
            val seen=BooleanArray(n);val queue=IntArray(n)
            fun foreground(index:Int)=((data[index].toInt() and 255)>threshold)==bright
            for(seed in 0 until n){
                if(seen[seed]||!foreground(seed))continue
                var read=0;var count=1;queue[0]=seed;seen[seed]=true;var touches=false
                val dxs=intArrayOf(-1,1,0,0);val dys=intArrayOf(0,0,-1,1)
                val edges=mutableListOf<P>();var light=0.0;var lap=0.0;var lapSq=0.0;var lapCount=0
                while(read<count){val index=queue[read++];val x=index%w;val y=index/w
                    if(x<=1||y<=1||x>=w-2||y>=h-2)touches=true
                    var boundary=false;val value=data[index].toInt() and 255;light+=value
                    if(x>0&&y>0&&x<w-1&&y<h-1){
                        val d=(data[index-1].toInt() and 255)+(data[index+1].toInt() and 255)+(data[index-w].toInt() and 255)+(data[index+w].toInt() and 255)-4*value
                        lap+=d;lapSq+=d.toDouble()*d;lapCount++
                    }
                    for(direction in 0..3){
                        val nx=x+dxs[direction];val ny=y+dys[direction]
                        if(nx !in 0 until w||ny !in 0 until h){boundary=true;continue}
                        val next=ny*w+nx
                        if(!foreground(next)){boundary=true;continue}
                        if(!seen[next]){seen[next]=true;queue[count++]=next}
                    }
                    if(boundary)edges.add(P(x,y))
                }
                if(touches||count<n*.12||count>n*.92)continue
                val q=quad(edges);if(q.size!=4)continue
                var area=0.0;for(i in 0..3)area+=q[i].x.toDouble()*q[(i+1)%4].y-q[(i+1)%4].x.toDouble()*q[i].y
                area/=2;if(area<n*.12||area>n*.92)continue
                val fill=count/area;if(fill<.65||fill>1.15)continue
                val normalized=q.flatMap{listOf(it.x.toDouble()/(w-1),it.y.toDouble()/(h-1))}
                try{ScanPerspective.validate(normalized)}catch(_:IllegalArgumentException){continue}
                val candidate=Candidate(normalized,w.toDouble()/h,light/count,
                    if(lapCount==0)0.0 else max(0.0,lapSq/lapCount-(lap/lapCount).pow(2)),fill.coerceAtMost(1.0))
                if(area>winnerArea){winner=candidate;winnerArea=area}
            }
        }
        return winner
    }
}

/** Monotonic, opt-in stability gate; a captured page must leave view before Auto rearms. */
class ScanStability {
    private var last:ScanDetector.Candidate?=null
    private var lastTime=-1L;private var since=0L;private var frames=0;private var missing=0
    private var armed=true
    data class Result(val candidate:ScanDetector.Candidate?,val stable:Boolean,val ready:Boolean)
    fun captured(){armed=false;frames=0;missing=0;last=null}
    fun reset(){last=null;frames=0;lastTime=-1;missing=0}
    fun update(candidate:ScanDetector.Candidate?,now:Long):Result{
        if(candidate==null){missing++;if(missing>=3)armed=true;last=null;frames=0;lastTime=now;return Result(null,false,false)}
        missing=0
        val previous=last
        val close=previous!=null && candidate.corners.indices.all{abs(candidate.corners[it]-previous.corners[it])<.018}
        if(!close||lastTime<0||now-lastTime !in 1..450){since=now;frames=1}else frames++
        val smooth=if(close)candidate.copy(corners=candidate.corners.indices.map{previous!!.corners[it]*.65+candidate.corners[it]*.35})else candidate
        last=smooth;lastTime=now
        val stable=frames>=6&&now-since>=1000&&candidate.autoEligible
        return Result(smooth,stable,stable&&armed)
    }
}

