        if(running&&boundRotation==rotation&&boundWidth==preview.width&&boundHeight==preview.height&&camera!=null)return
        val token=++session
        val future=ProcessCameraProvider.getInstance(this)
        future.addListener({
            if(isFinishing||isDestroyed||token!=session)return@addListener
            try{
                val p=future.get();provider=p;p.unbindAll()
                val live=Preview.Builder().setTargetAspectRatio(AspectRatio.RATIO_4_3).setTargetRotation(rotation).build()
                val still=ImageCapture.Builder().setCaptureMode(ImageCapture.CAPTURE_MODE_MINIMIZE_LATENCY).setTargetAspectRatio(AspectRatio.RATIO_4_3).setTargetRotation(rotation).build()
                val frames=ImageAnalysis.Builder().setTargetResolution(android.util.Size(640,480)).setTargetRotation(rotation).setBackpressureStrategy(ImageAnalysis.STRATEGY_KEEP_ONLY_LATEST).build()
                live.setSurfaceProvider(preview.surfaceProvider)
