                capture=still;analysis=frames;boundRotation=rotation;boundWidth=preview.width;boundHeight=preview.height;running=true;latest=null;stability.reset()
                frames.setAnalyzer(analyzer){image->analyze(image,token)}
                torchOn=false;torch.text="Torch off";torch.isEnabled=camera?.cameraInfo?.hasFlashUnit()==true
                zoom.progress=0;zoom.isEnabled=true;retry.visibility=View.GONE
                status.text="Keep the whole page in view. Tap Capture anytime.";updateControls()
            }catch(_:Exception){running=false;capture=null;shutter.isEnabled=false;torch.isEnabled=false;zoom.isEnabled=false;status.text="Live camera unavailable on this device. Use Gallery or Other scanner."}
        },ContextCompat.getMainExecutor(this))
    }
    private fun analyze(image:ImageProxy,token:Int){
        try{
            val now=SystemClock.elapsedRealtime();if(now-lastAnalysis<200)return;lastAnalysis=now
            val rect=image.cropRect;val plane=image.planes[0]
            val gray=ScanDetector.sample(plane.buffer,plane.rowStride,plane.pixelStride,rect.left,rect.top,rect.width(),rect.height(),image.imageInfo.rotationDegrees)
            val candidate=ScanDetector.detect(gray)
            runOnUiThread{
                if(!running||!resumed||busy||isFinishing||isDestroyed||token!=session)return@runOnUiThread
                val result=stability.update(candidate,now);latest=result.candidate;latestAt=now
                overlay.update(result.candidate?.corners,result.stable)
                status.text=when{pages.size>=30->"30 pages ready. Review and save before adding more."
                    result.candidate==null->"No clear page outline. Manual Capture is available."
                    autoMode&&result.ready->"Page steady — capturing…"
                    autoMode&&result.stable->"Lift the page out of view before the next auto capture."
                    autoMode->"Hold steady. Improve light or use manual Capture."
                    else->"Page outline found. Tap Capture or turn on Auto."}
                if(autoMode&&result.ready&&pages.size<30)takePhoto(true)
            }
        }catch(_:Exception){/* An uncertain/malformed frame never disables manual capture. */}
        finally{image.close()}
    }
