        val still=capture?:return;if(busy||!running||!resumed||pages.size>=30)return
        busy=true;updateControls();status.text="Saving original page…"
        val proposed=if(automatic&&SystemClock.elapsedRealtime()-latestAt<400)latest else null
        stability.captured();overlay.update(null,false)
        val app=applicationContext
        ScanWork.executor.execute{
            try{
                require(store.folder.usableSpace>64L*1024*1024){"Free storage before capturing."}
                val output=store.newCapture()
                runOnUiThread{
                    if(isFinishing||isDestroyed){ScanWork.executor.execute{store.finishCapture(false)};return@runOnUiThread}
                    try { still.takePicture(ImageCapture.OutputFileOptions.Builder(output).build(),ContextCompat.getMainExecutor(this),object:ImageCapture.OnImageSavedCallback{
                        override fun onImageSaved(result:ImageCapture.OutputFileResults){
                            ScanWork.executor.execute{
                                var saved=emptyList<String>();var warning=false
                                try{
                                    saved=ScanDraftStore(app).finishCapture(true)
                                    if(proposed!=null){
                                        val bounds=StudioImages.load(saved.last(),160)
                                        val ratio=bounds.width.toDouble()/bounds.height;bounds.recycle()
                                        // ViewPort aligns streams; refuse a stale/aspect-mismatched crop rather than cut content.
                                        if(abs(ratio/proposed.ratio-1)<.035){
                                            try{saved=ScanDraftStore(app).edit(listOf(saved.last()),"original",null,proposed.corners)}catch(_:Exception){warning=true}
                                        }else warning=true
                                    }
                                    val completed=saved
                                    runOnUiThread{if(!isDestroyed){pages=completed;busy=false;updatePages();status.text=if(warning)"Photo saved. Check and adjust its corners in review." else "Page saved. Lift it away before the next auto capture."}}
                                }catch(_:Exception){runOnUiThread{if(!isDestroyed){busy=false;status.text="Could not finish this page. Earlier pages are safe; retry or review.";updateControls()}}}
                            }
                        }
                        override fun onError(error:ImageCaptureException){ScanWork.executor.execute{try{store.finishCapture(false)}catch(_:Exception){};runOnUiThread{if(!isDestroyed){busy=false;status.text="Capture failed. Earlier pages are safe.";updateControls()}}}}
                    }) } catch(_:Exception) {
                        ScanWork.executor.execute { try { store.finishCapture(false) } catch(_:Exception) {}
                            runOnUiThread { if(!isDestroyed) { busy=false;status.text="Capture was interrupted. Earlier pages are safe.";updateControls() } }
                        }
                    }
                }
            }catch(_:Exception){runOnUiThread{if(!isDestroyed){busy=false;status.text="Could not start this page. Review your saved pages or free storage.";updateControls()}}}
        }
    }
    private fun updateControls(){shutter.isEnabled=running&&!busy&&pages.size<30;done.isEnabled=!busy;auto.isEnabled=!busy;torch.isEnabled=!busy&&camera?.cameraInfo?.hasFlashUnit()==true;zoom.isEnabled=running&&!busy}
    private fun updatePages(){
        done.text="Review (${pages.size})";updateControls();if(boundRotation<0&&resumed)preview.post{bindCamera()};strip.removeAllViews()
        // Only bounded thumbnails are decoded, serially; stale callbacks cannot attach to a new strip.
        val current=pages.toList();val generation=++thumbnailGeneration
        current.forEachIndexed{index,path->
            val box=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;gravity=Gravity.CENTER;contentDescription="Page ${index+1}. Review saved pages.";setOnClickListener{finishReview()}}
            val image=ImageView(this).apply{scaleType=ImageView.ScaleType.FIT_CENTER};box.addView(image,LinearLayout.LayoutParams(dp(48),dp(44)))
            box.addView(label("${index+1}").apply{textSize=11f;setPadding(0,0,0,0)})
            strip.addView(box,LinearLayout.LayoutParams(dp(60),dp(68)))
            ScanWork.executor.execute{try{val bitmap=StudioImages.load(path,128);runOnUiThread{if(isDestroyed||generation!=thumbnailGeneration)bitmap.recycle()else image.setImageBitmap(bitmap)}}catch(_:Exception){}}
        }
    }
    private var thumbnailGeneration=0
    private fun toggleTorch(){if(busy)return;val c=camera?:return;if(!c.cameraInfo.hasFlashUnit())return
        val next=!torchOn;val task=c.cameraControl.enableTorch(next)
        task.addListener({try{task.get();torchOn=next;torch.text=if(next)"Torch on" else "Torch off";stability.reset()}catch(_:Exception){status.text="Torch could not be changed on this device."}},ContextCompat.getMainExecutor(this))}
    private fun finishReview(action:String="review"){if(busy){status.text="Finishing this page. Please wait.";return};setResult(RESULT_OK,Intent().putExtra("action",action));finish()}
    override fun onConfigurationChanged(newConfig:Configuration){super.onConfigurationChanged(newConfig);applyLayout();boundRotation=-1;running=false;updateControls();stability.reset();latest=null;preview.post{bindCamera()}}
    override fun onResume(){super.onResume();resumed=true;if(!busy&&checkSelfPermission(Manifest.permission.CAMERA)==PackageManager.PERMISSION_GRANTED)preview.post{bindCamera()}}
    override fun onPause(){resumed=false;super.onPause();latest=null;stability.reset();overlay.update(null,false);camera?.cameraControl?.enableTorch(false);torchOn=false;torch.text="Torch off"}
    override fun onDestroy(){session++;thumbnailGeneration++;running=false;analysis?.clearAnalyzer();provider?.unbindAll();analyzer.shutdown();super.onDestroy()}
}

class ScanOutline(context:android.content.Context):View(context){
    private var corners:List<Double>?=null;private var stable=false
    fun update(points:List<Double>?,steady:Boolean){corners=points;stable=steady;invalidate()}
    override fun onDraw(canvas:Canvas){super.onDraw(canvas);val q=corners?:return
        val path=Path().apply{moveTo((q[0]*width).toFloat(),(q[1]*height).toFloat());for(i in 1..3)lineTo((q[i*2]*width).toFloat(),(q[i*2+1]*height).toFloat());close()}
        val outlineColor=if(stable)Color.rgb(89,231,184)else Color.rgb(255,218,115)
        canvas.drawPath(path,Paint(Paint.ANTI_ALIAS_FLAG).apply{this.color=outlineColor;style=Paint.Style.STROKE;strokeWidth=3*resources.displayMetrics.density})
        for(i in 0..3)canvas.drawCircle((q[i*2]*width).toFloat(),(q[i*2+1]*height).toFloat(),5*resources.displayMetrics.density,Paint(Paint.ANTI_ALIAS_FLAG).apply{this.color=outlineColor})
    }
}

