/** Uses the installed camera app, without an app camera permission or a heavy
 * Play-services scanning Activity. Each confirmed capture appends one page. */
class HyzenCameraCapture(private val activity: MainActivity, messenger: BinaryMessenger) {
    private val store = ScanDraftStore(activity)
    private val worker = NativeDocumentWork.executor
    private val channel = MethodChannel(messenger, "com.hyzen.pharmd/camera_pages")
    private var pending: MethodChannel.Result? = null
    private var busy = false
    init {
        channel.setMethodCallHandler { call, result ->
            if (pending != null && call.method != "needsRecovery") { result.error("busy", "Finish the pending camera capture first.", null); return@setMethodCallHandler }
            if (HyzenLiveScanner.active && call.method != "needsRecovery") { result.error("busy", "Finish the live camera first.", null); return@setMethodCallHandler }
            try { if(call.method!="needsRecovery") { ScanExportJobs.requireDraftAccess(call.argument<String>("exportJob"),call.method); check(!HyzenDocumentScanner.active) { "Finish the other scanner first." } } }
            catch(e:Exception){result.error("busy",e.message,null);return@setMethodCallHandler}
            if (call.method == "capture") {
                if (activity.checkSelfPermission(android.Manifest.permission.CAMERA) != android.content.pm.PackageManager.PERMISSION_GRANTED) {
                    result.error("camera_permission", "Camera access is needed. Use Scan to allow it, or choose gallery images.", null); return@setMethodCallHandler
                }
                if (pending != null || busy) { result.error("busy", "Finish this page first.", null); return@setMethodCallHandler }
                busy = true
                worker.execute {
                var prepared = false
                try {
                    ScanExportJobs.requireDraftAccess()
                    val file = store.newCapture(); prepared = true
                    val uri = FileProvider.getUriForFile(activity, "${activity.packageName}.updates", file)
                    val intent = Intent(MediaStore.ACTION_IMAGE_CAPTURE).apply {
                        putExtra(MediaStore.EXTRA_OUTPUT, uri)
                        clipData = ClipData.newRawUri("Scan page", uri)
                        addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION or Intent.FLAG_GRANT_WRITE_URI_PERMISSION)
                    }
                    activity.runOnUiThread {
                        try { pending = result; busy = false; activity.startActivityForResult(intent, REQUEST) }
                        catch (_: Exception) { receive(REQUEST,Activity.RESULT_CANCELED) }
                    }
                } catch (_: Exception) {
                    if (prepared) { store.finishCapture(false); store.acknowledge(); pending = null }
                    activity.runOnUiThread { busy = false; result.error("camera", "Camera unavailable. Choose gallery images instead.", null) }
                }
                }
                return@setMethodCallHandler
            }
            if (busy) { result.error("busy", "Preparing your page…", null); return@setMethodCallHandler }
            busy = true
            worker.execute {
                try {
                    if(call.method!="needsRecovery") { ScanExportJobs.requireDraftAccess(call.argument<String>("exportJob"),call.method); check(!HyzenLiveScanner.active && !HyzenDocumentScanner.active) { "Finish the scanner first." } }
                    val answer: Any = when (call.method) {
                        "archive" -> store.archive(call.argument<String>("id") ?: "")
                        "openArchive" -> store.openArchive(call.argument<String>("id") ?: "")
                        "deleteArchive" -> store.deleteArchive(call.argument<String>("id") ?: "")
                        "needsRecovery" -> store.needsRecovery() && pending == null
                        "recover" -> store.recover().also { store.acknowledge() }
                        "addImages" -> store.add(call.argument<List<String>>("paths") ?: emptyList())
                        "replace" -> store.replace(call.argument<List<String>>("paths") ?: emptyList())
                        "undoRemoval" -> store.undoRemoval()
                        "undo" -> store.undo(call.argument<String>("path") ?: "")
                        "reset" -> store.reset(call.argument<String>("path") ?: "")
                        "redetect" -> mapOf("corners" to store.redetect(call.argument<String>("path") ?: ""))
                        "editPreview" -> store.editPreview(call.argument<String>("path") ?: "")
                        "originalInfo" -> store.originalInfo(call.argument<String>("path") ?: "")
                        "rotate" -> store.rotate(call.argument<String>("path") ?: "")
                        "edit" -> store.edit(call.argument<List<String>>("paths") ?: emptyList(), call.argument<String>("filter") ?: "original", call.argument<List<Double>>("crop"), call.argument<List<Double>>("quad"), call.argument<Number>("brightness")?.toDouble() ?: 0.0, call.argument<Number>("contrast")?.toDouble() ?: 1.0)
                        "clear" -> { store.clear(); true }
                        else -> { activity.runOnUiThread { busy = false; result.notImplemented() }; return@execute }
                    }
                    activity.runOnUiThread { busy = false; result.success(answer) }
                } catch (e: Throwable) {
                    activity.runOnUiThread { busy = false; result.error("scan_page", when(call.method) {
                        "archive" -> "PDF saved, but editable backup failed. Your current draft is retained."
                        "openArchive" -> "Could not reopen this scan. Finish any current draft first; older scans may not have editable originals."
                        else -> "Could not prepare this page. Your earlier pages are safe."
                    }, null) }
                }
            }
        }
    }
    fun receive(code: Int, resultCode: Int): Boolean {
        if (code != REQUEST) return false
        val result = pending; pending = null; busy = true
        worker.execute {
            try {
                val pages = store.finishCapture(resultCode == Activity.RESULT_OK)
                if (result != null) store.acknowledge()
                activity.runOnUiThread { busy = false; result?.success(pages); channel.invokeMethod("draftReady", null) }
            } catch (_: Throwable) {
                activity.runOnUiThread { busy = false; result?.error("capture", "Could not add this page. Your earlier pages are safe.", null) }
            }
        }
        return true
    }
    fun close() { pending = null; /* Shared process queue outlives this Activity. */ }
    companion object { const val REQUEST = 8892 }
}

package com.hyzen.pharmd

import android.app.Activity
import android.content.Intent
import com.google.mlkit.vision.documentscanner.GmsDocumentScannerOptions
import com.google.mlkit.vision.documentscanner.GmsDocumentScanning
import com.google.mlkit.vision.documentscanner.GmsDocumentScanningResult
import io.flutter.plugin.common.BinaryMessenger
import io.flutter.plugin.common.MethodChannel
import java.io.File

/** Google's native document viewfinder supplies auto/manual capture, page-edge
 * correction, cleanup and multi-page review. Only JPEG output is requested:
 * Hyzen composes the final PDF once, after its durable page review. */
class HyzenDocumentScanner(private val activity: MainActivity, messenger: BinaryMessenger) {
    private val store = ScanDraftStore(activity)
    private var pending: MethodChannel.Result? = null
    companion object { @Volatile var active = false; private set }
    private val worker = NativeDocumentWork.executor
    private val channel = MethodChannel(messenger, "com.hyzen.pharmd/document_scanner")
    private val cameraChannel = MethodChannel(messenger, "com.hyzen.pharmd/camera_pages")
    private val requestCode = 8891
    init {
        channel.setMethodCallHandler { call, result ->
            if (call.method != "scan") { result.notImplemented(); return@setMethodCallHandler }
            if (HyzenLiveScanner.active) { result.error("busy", "Finish the live camera first.", null); return@setMethodCallHandler }
            if (active) { result.error("busy", "Finish the current scan first.", null); return@setMethodCallHandler }
            try { ScanExportJobs.requireDraftAccess(); check(!store.hasPendingCapture()) { "Recover the pending camera page first." } }
            catch(e:Exception){result.error("busy",e.message,null);return@setMethodCallHandler}
            val available = 30 - store.pages().size
            if (available <= 0) { result.error("limit", "Save these 30 pages before scanning more.", null); return@setMethodCallHandler }
            pending = result
            active = true
            store.beginScan()
            val options = GmsDocumentScannerOptions.Builder()
                .setGalleryImportAllowed(true).setPageLimit(available)
                .setResultFormats(GmsDocumentScannerOptions.RESULT_FORMAT_JPEG)
                .setScannerMode(GmsDocumentScannerOptions.SCANNER_MODE_FULL).build()
            GmsDocumentScanning.getClient(options).getStartScanIntent(activity)
                .addOnSuccessListener { sender ->
                    if (active && !activity.isFinishing) {
                        try { activity.startIntentSenderForResult(sender, requestCode, null, 0, 0, 0) }
                        catch (_: Exception) { fail() }
                    }
                }.addOnFailureListener { fail() }
        }
    }
    private fun fail() {
        store.acknowledge()
        pending?.error("scanner_unavailable", "Document scanner is unavailable. Update Google Play services, or choose the basic camera / gallery.", null)
        pending = null; active = false
    }
    fun receive(code: Int, resultCode: Int, intent: Intent?): Boolean {
        if (code != requestCode) return false
        // Process results even when Android recreated this Activity and there
        // is no live MethodChannel callback to the previous Flutter isolate.
        val result = pending; pending = null
        if (resultCode != Activity.RESULT_OK) {
            active = false; store.acknowledge(); result?.success(store.pages()); return true
        }
        worker.execute {
            val staged = mutableListOf<File>()
            try {
                val pages = GmsDocumentScanningResult.fromActivityResultIntent(intent)?.pages
                    ?: error("No scanned pages returned")
                require(pages.isNotEmpty() && pages.size + store.pages().size <= 30)
                for (page in pages) {
                    val file = File.createTempFile("scan_result_", ".jpg", activity.cacheDir)
                    staged.add(file)
                    activity.contentResolver.openInputStream(page.imageUri)?.use { input ->
                        file.outputStream().use { output ->
                            val buffer = ByteArray(65536); var total = 0L
                            while (true) {
                                val n = input.read(buffer); if (n < 0) break
                                total += n; require(total <= 40L * 1024 * 1024)
                                output.write(buffer, 0, n)
                            }
                        }
                    } ?: error("Scan unavailable")
                }
                val saved = store.addProcessed(staged.map { it.path })
                // Keep recovery flag until the new Flutter screen reads it.
                activity.runOnUiThread {
                    active = false
                    result?.success(saved)
                    cameraChannel.invokeMethod("draftReady", null)
                }
            } catch (_: Throwable) {
                activity.runOnUiThread {
                    active = false
                    result?.error("scan", "Could not add scanned pages. Your earlier pages are safe.", null)
                    cameraChannel.invokeMethod("draftReady", null)
                }
            } finally { staged.forEach { it.delete() } }
        }
        return true
    }
    fun close() { pending = null; /* Shared process queue outlives this Activity. */ }
}

