/** Local PDF operations. Pages are rasterized so input documents are never modified. */
class StudioPdfEngine(private val activity: MainActivity, engine: FlutterEngine) {
    private val worker = NativeDocumentWork.executor
    private val clientId = java.util.UUID.randomUUID().toString()

    init {
        NativeDocumentWork.maintain(activity)
        MethodChannel(engine.dartExecutor.binaryMessenger, "com.hyzen.pharmd/studio_work")
            .setMethodCallHandler { call, result ->
                try {
                    val id = call.argument<String>("id") ?: ""
                    when (call.method) {
                        "begin" -> result.success(StudioWorkJobs.begin(clientId))
                        "cancel" -> result.success(StudioWorkJobs.cancel(id, clientId))
                        "check" -> { StudioWorkJobs.check(id, clientId); result.success(true) }
                        "commit" -> result.success(StudioWorkJobs.commit(id, clientId))
                        "finish" -> result.success(StudioWorkJobs.finish(id, clientId))
                        else -> result.notImplemented()
                    }
                } catch (_: java.util.concurrent.CancellationException) { result.error("studio_cancelled", "Operation cancelled. Original retained.", null) }
                catch (e: Exception) { result.error("studio_work", e.message, null) }
            }
        MethodChannel(engine.dartExecutor.binaryMessenger, "com.hyzen.pharmd/scan_export")
            .setMethodCallHandler { call, result ->
                try {
                    when (call.method) {
                        "begin" -> { check(!HyzenLiveScanner.active && !HyzenDocumentScanner.active && !ScanDraftStore(activity).hasPendingCapture()) { "Finish the current scanner first." }; result.success(ScanExportJobs.begin(clientId, call.argument<Boolean>("retainFinalization") == true)) }
                        "finish" -> result.success(ScanExportJobs.finish(call.argument<String>("id") ?: ""))
                        "cancel" -> result.success(ScanExportJobs.cancel(call.argument<String>("id") ?: ""))
                        else -> result.notImplemented()
                    }
                } catch (e: Exception) { result.error("scan_export_busy", e.message, null) }
            }
        MethodChannel(engine.dartExecutor.binaryMessenger, "com.hyzen.pharmd/pdf_studio")
            .setMethodCallHandler { call, result ->
                val studioJob = call.argument<String>("studioJob")
                worker.execute {
                    var started = false
                    try {
                        if (studioJob != null) { StudioWorkJobs.start(studioJob, clientId); started = true }
                        val probe: () -> Unit = { if (studioJob != null) StudioWorkJobs.check(studioJob, clientId) }
                        val directory = studioJob?.let { StudioWorkJobs.directory(activity, it, clientId) }
                        val documentOps = StudioDocumentOps(activity, directory, probe)
                        val formats = StudioExportFormats(activity)
                        val answer: Any = when (call.method) {
                            "pageCount" -> {
                                val path = call.argument<String>("path") ?: error("Missing PDF path")
                                ParcelFileDescriptor.open(File(path), ParcelFileDescriptor.MODE_READ_ONLY).use { fd ->
                                    PdfRenderer(fd).use { it.pageCount }
                                }
                            }
                            "compose" -> {
                                val pages = call.argument<List<Map<String, Any?>>>("pages") ?: error("No pages selected")
                                if (call.argument<Boolean>("flatten") == true) formats.compose(pages, probe, directory) else documentOps.compose(pages)
                            }
                            "protect" -> documentOps.protect(call.argument<String>("path") ?: error("Missing PDF"), call.argument<String>("password") ?: error("Missing password"))
                            "ocr" -> documentOps.ocr(call.argument<String>("path") ?: error("Missing PDF"))
                            "compress" -> documentOps.compress(call.argument<String>("path") ?: error("Missing PDF"), call.argument<String>("preset") ?: "balanced")
                            "richDocument" -> StudioRichWriter(activity, directory, probe).write(call.argument<List<Map<String,Any?>>>("blocks") ?: error("Missing document"),call.argument<String>("format") ?: "pdf")
                            "imagesToPdf" -> {
                                val job = call.argument<String>("exportJob") ?: ScanExportJobs.begin()
                                try {
                                    check(!HyzenLiveScanner.active) { "Finish the live camera before exporting." }
                                    val paths = call.argument<List<String>>("paths") ?: error("No images selected")
                                    ScanExportJobs.start(job)
                                    val outputDirectory = ScanExportJobs.outputDirectory(activity,job)
                                    val scanProbe = { ScanExportJobs.check(job); probe() }
                                    val path = if (call.argument<Boolean>("scanDraft") == true) ScanDraftStore(activity).exportPdf(paths, call.argument<Boolean>("highQuality") == true, call.argument<String>("paper") ?: "a4", call.argument<String>("orientation") ?: "auto", call.argument<Int>("margin") ?: 16, scanProbe, directory ?: outputDirectory) else documentOps.imagesToPdf(paths, paper = call.argument<String>("paper") ?: "a4", orientation = call.argument<String>("orientation") ?: "auto", margin = call.argument<Int>("margin") ?: 16, checkCancelled = scanProbe, outputDirectory = directory ?: outputDirectory)
                                    ScanExportJobs.complete(job, path)
                                } finally { ScanExportJobs.endRendering(job) }
                            }
                            "textToPdf" -> formats.textToPdf(call.argument<String>("text") ?: "", probe, directory)
                            "textToDocx" -> formats.textToDocx(call.argument<String>("text") ?: "", probe, directory)
                            "textFile" -> {
                                File.createTempFile("studio_note_", ".txt", directory ?: activity.cacheDir).apply {
                                    writeText(call.argument<String>("text") ?: "")
                                }.absolutePath
                            }
                            "readText" -> {
                                val source = File(call.argument<String>("path") ?: error("Missing document"))
                                require(source.length() <= 2_000_000L) { "Text file is too large." }
                                source.readText(Charsets.UTF_8)
                            }
                            "pagesToImages" -> formats.pagesToImages(
                                call.argument<String>("path") ?: error("Missing PDF"),
                                call.argument<String>("format") ?: "png", probe, directory
                            )
                            "renderPage" -> renderPage(
                                call.argument<String>("path") ?: error("Missing PDF"),
                                call.argument<Int>("index") ?: 0,
                                call.argument<Int>("maxEdge") ?: 1800
                            )
                            "getEditState" -> stateFile(call.argument<String>("path") ?: error("Missing state")).readText()
                            "setEditState" -> {
                                val content = call.argument<String>("json") ?: error("Missing annotation state")
                                require(content.length <= 500_000) { "Too many annotations" }
                                val target = stateFile(call.argument<String>("path") ?: error("Missing state"))
                                val partial = File(target.parentFile, "${target.name}.part")
                                try {
                                    partial.writeText(content)
                                    require(partial.renameTo(target)) { "Could not save annotations" }
                                } finally { if (partial.exists()) partial.delete() }
                                true
                            }
                            else -> {
                                activity.runOnUiThread { result.notImplemented() }
                                return@execute
                            }
                        }
                        probe()
                        if (started && studioJob != null) { StudioWorkJobs.end(studioJob, clientId); started = false }
                        activity.runOnUiThread { result.success(answer) }
                    } catch (e: java.util.concurrent.CancellationException) {
                        activity.runOnUiThread { result.error(if (studioJob != null) "studio_cancelled" else "export_cancelled", "Operation cancelled. Your original and edits are retained.", null) }
                    } catch (_: OutOfMemoryError) {
                        activity.runOnUiThread { result.error("pdf_memory", "Not enough memory. Save fewer pages; your draft is safe.", null) }
                    } catch (e: Exception) {
                        activity.runOnUiThread {
                            result.error("pdf_studio", e.message ?: "PDF operation failed", null)
                        }
                    } finally { if (started && studioJob != null) StudioWorkJobs.end(studioJob, clientId) }
                }
            }
    }

    private fun stateFile(path: String): File {
        val root = File(activity.filesDir, "pdf_studio/state").canonicalFile
        val target = File(path).canonicalFile
        require(target.parentFile == root && target.name.endsWith("_state.json") && target.isFile) {
            "Annotation state is unavailable"
        }
        return target
    }

    private fun renderPage(path: String, index: Int, maxEdge: Int = 1800): Map<String, Any> =
        PdfPagePreviewRenderer.render(path, index, maxEdge)

    fun close() { ScanExportJobs.abandon(clientId); StudioWorkJobs.abandon(clientId) }
}

