            'Add Note',
            Icons.note_add_outlined,
            edit,
            group: 'Quick edits',
          ),
        ],
        ReaderAction(
          'Zoom in',
          Icons.zoom_in_rounded,
          () => _tools.run('in', context),
          group: 'View',
