package com.hyzen.pharmd

import android.content.Context
import android.graphics.*
import org.json.JSONArray
import org.json.JSONObject
import java.io.File
import java.io.FileOutputStream

/** Immutable imported bytes plus reversible, bounded preview transforms.
 * A legacy page can preserve only the processed bytes that still exist. */
class ScanDraftStore(private val context: Context) {
    private val prefs = context.getSharedPreferences("hyzen_scan_draft", Context.MODE_PRIVATE)
    val folder = File(context.filesDir, "scan_draft").apply { mkdirs() }
    private fun valid(path: String) = File(path).let {
        it.canonicalFile.parentFile == folder.canonicalFile && it.isFile && it.length() > 0
    }
    fun pages(): List<String> {
        val raw = JSONArray(prefs.getString("pages", "[]"))
        return (0 until raw.length()).map { raw.getString(it) }.filter { valid(it) }
    }
    private fun records() = JSONObject(prefs.getString("pageGraph", "{}"))
    private fun blank() = JSONObject().put("geometry", JSONArray()).put("filter", "original")
    private fun copy(value: JSONObject) = JSONObject(value.toString())
    private fun write(file: File, block: (FileOutputStream) -> Unit) {
        FileOutputStream(file).use { block(it); it.fd.sync() }
    }
    private fun original(file: File, created: MutableList<File>): File {
        val raw = File.createTempFile("original_", ".image", folder)
        created.add(raw)
        write(raw) { out -> file.inputStream().use { it.copyTo(out) } }
        return raw
    }
    private fun record(path: String, all: JSONObject, created: MutableList<File>): JSONObject {
        if (all.has(path)) return copy(all.getJSONObject(path))
        // Lazy, reversible migration: never invent a missing pre-edit original.
        val raw = original(File(path), created)
        return JSONObject().put("original", raw.path).put("source", "legacy_processed")
            .put("state", blank()).put("history", JSONArray())
    }
    private fun commit(paths: List<String>, all: JSONObject, consumeCapture: Boolean = false, removed: JSONArray? = null, clearRemoved: Boolean = false) {
        val kept = JSONObject()
        paths.forEach { if (all.has(it)) kept.put(it, all.getJSONObject(it)) }
        val edit = prefs.edit().putString("pages", JSONArray(paths).toString()).putString("pageGraph", kept.toString())
        if (consumeCapture) edit.remove("cameraPath")
        if (removed != null) edit.putString("removedPages", removed.toString())
        if (clearRemoved) edit.remove("removedPages")
        check(edit.commit()) { "Could not save scan draft" }
    }
    fun newCapture(): File {
        require(pages().size < 30) { "Save these 30 pages before scanning more." }
        check(!prefs.contains("cameraPath")) { "Recover the pending page first." }
        val output = File.createTempFile("camera_", ".jpg", folder)
        check(prefs.edit().putString("cameraPath", output.path).putBoolean("recover", true).commit())
        return output
    }
    fun finishCapture(ok: Boolean): List<String> {
        val source = prefs.getString("cameraPath", null)?.let { File(it) }
        if (ok && source != null && valid(source.path)) {
            // Malformed camera output is retained for diagnosis but not retried forever.
            val bounds = BitmapFactory.Options().apply { inJustDecodeBounds = true }
            BitmapFactory.decodeFile(source.path, bounds)
            if (bounds.outWidth <= 0 || bounds.outHeight <= 0) {
                check(prefs.edit().remove("cameraPath").commit())
                throw IllegalArgumentException("Camera image unavailable")
            }
            addInternal(listOf(source.path), "camera_capture", true)
            source.delete() // Only after both page and pending-capture state commit.
        } else {
            check(prefs.edit().remove("cameraPath").commit())
            source?.takeIf { it.canonicalFile.parentFile == folder.canonicalFile }?.delete()
        }
        return pages()
    }
    fun add(paths: List<String>): List<String> = addInternal(paths, "imported_image", false)
    fun addProcessed(paths: List<String>): List<String> = addInternal(paths, "scanner_processed", false)
    private fun addInternal(paths: List<String>, sourceKind: String, consumeCapture: Boolean): List<String> {
        val current = pages().toMutableList()
        require(current.size + paths.size <= 30) { "Choose up to 30 pages per PDF." }
        val all = records(); val created = mutableListOf<File>()
        try {
            for (path in paths) {
                val file = File(path).canonicalFile
                require(file.path.startsWith(context.filesDir.canonicalPath + "/") || file.path.startsWith(context.cacheDir.canonicalPath + "/"))
                require(file.length() in 1..(40L * 1024 * 1024))
                val raw = original(file, created)
                val entry = JSONObject().put("original", raw.path).put("source", sourceKind)
                    .put("state", blank()).put("history", JSONArray())
                val preview = render(entry, created)
                current.add(preview.path); all.put(preview.path, entry)
            }
            commit(current, all, consumeCapture)
            return current
        } catch (e: Throwable) { created.forEach { it.delete() }; throw e }
    }
    fun replace(paths: List<String>): List<String> {
        val current = pages(); val all = records()
        require(paths.size <= 30 && paths.distinct().size == paths.size && paths.all { it in current })
        val removed = current.filter { it !in paths }
        if (removed.isEmpty()) { commit(paths,all);return paths }
        val previous = JSONArray(prefs.getString("removedPages", "[]"))
        val trash = JSONArray()
        removed.forEach { path ->
            trash.put(JSONObject().put("path",path).put("index",current.indexOf(path)).put("record",all.optJSONObject(path)))
        }
        // Publish the new page list and its removal undo record together.
        commit(paths, all, removed=trash)
        for(i in 0 until previous.length()) {
            val entry=previous.getJSONObject(i)
            val path=entry.getString("path")
            if (path !in current && valid(path)) File(path).delete()
            entry.optJSONObject("record")?.optString("original")?.takeIf { valid(it) }?.let { File(it).delete() }
        }
        return paths
    }
    fun undoRemoval(): List<String> {
        val removed=JSONArray(prefs.getString("removedPages", "[]"))
        if(removed.length()==0) return pages()
        val next=pages().toMutableList();val all=records()
        require(next.size+removed.length()<=30) { "Save some pages before restoring removed pages." }
        for(i in 0 until removed.length()) {
            val item=removed.getJSONObject(i);val path=item.getString("path")
            require(valid(path) && path !in next)
            next.add(item.getInt("index").coerceIn(0,next.size),path)
            item.optJSONObject("record")?.let { all.put(path,it) }
        }
        commit(next,all,clearRemoved=true)
        return next
    }
    private fun change(paths: List<String>, transform: (JSONObject) -> Unit): List<String> {
        val current = pages(); val all = records(); val created = mutableListOf<File>()
        require(paths.isNotEmpty() && paths.distinct().size == paths.size && paths.all { it in current })
        val replacements = mutableMapOf<String, String>()
        try {
            for (path in paths) {
                val entry = record(path, all, created)
                transform(entry)
                val output = render(entry, created)
                all.put(output.path, entry); replacements[path] = output.path
            }
            val next = current.map { replacements[it] ?: it }
            commit(next, all)
            paths.forEach { File(it).delete() }
            return next
        } catch (e: Throwable) { created.forEach { it.delete() }; throw e }
    }
    private fun remember(entry: JSONObject) {
        val history = entry.getJSONArray("history")
        history.put(copy(entry.getJSONObject("state")))
        while (history.length() > 20) history.remove(0)
    }
    fun rotate(path: String): List<String> = change(listOf(path)) { entry ->
        remember(entry)
        val geometry = entry.getJSONObject("state").getJSONArray("geometry")
        require(geometry.length() < 128) { "Reset this page before more edits." }
        geometry.put(JSONObject().put("rotate", true))
    }
    fun edit(paths: List<String>, filter: String, crop: List<Double>?, quad: List<Double>? = null, brightness: Double = 0.0, contrast: Double = 1.0): List<String> {
        require(brightness.isFinite() && brightness in -1.0..1.0 && contrast.isFinite() && contrast in .5..2.0)
        require(filter in setOf("original", "gray", "contrast", "bw", "enhance"))
        if (crop != null) require(crop.size == 4 && crop.all { it.isFinite() && it in 0.0..1.0 } && crop[0] < crop[2] && crop[1] < crop[3])
        if (quad != null) ScanPerspective.validate(quad)
        require(crop == null || quad == null)
        return change(paths) { entry ->
            remember(entry)
            val state = entry.getJSONObject("state")
            if (crop != null) {
                val geometry = state.getJSONArray("geometry")
                require(geometry.length() < 128) { "Reset this page before more edits." }
                geometry.put(JSONObject().put("crop", JSONArray(crop)))
            }
            if (quad != null) {
                val geometry = state.getJSONArray("geometry")
                require(geometry.length() < 128)
                geometry.put(JSONObject().put("quad", JSONArray(quad)))
            }
            state.put("filter", filter).put("brightness", brightness).put("contrast", contrast)
        }
    }
    fun undo(path: String): List<String> = change(listOf(path)) { entry ->
        val history = entry.getJSONArray("history")
        if (history.length() > 0) entry.put("state", history.remove(history.length() - 1))
    }
    fun reset(path: String): List<String> = change(listOf(path)) { entry -> remember(entry); entry.put("state", blank()) }
    fun originalInfo(path: String): Map<String, String> {
        require(path in pages())
        val entry = records().optJSONObject(path)
        return mapOf("path" to (entry?.getString("original") ?: path), "source" to (entry?.getString("source") ?: "legacy_processed"))
    }
    fun editPreview(path: String): Map<String, Any> {
        require(path in pages())
        val entry = records().optJSONObject(path)
            ?: return mapOf("bytes" to File(path).readBytes(), "filter" to "original")
        val preview = copy(entry)
        val filter = preview.getJSONObject("state").getString("filter")
        val brightness = preview.getJSONObject("state").optDouble("brightness", 0.0)
        val contrast = preview.getJSONObject("state").optDouble("contrast", 1.0)
        preview.getJSONObject("state").put("filter", "original").put("brightness", 0.0).put("contrast", 1.0)
        val created = mutableListOf<File>()
        try { return mapOf("bytes" to render(preview, created).readBytes(), "filter" to filter, "brightness" to brightness, "contrast" to contrast) }
        finally { created.forEach { it.delete() } }
    }
    fun redetect(path: String): List<Double>? {
        require(path in pages())
        val created=mutableListOf<File>()
        try {
            val all=records();val entry=record(path,all,created)
            entry.getJSONObject("state").put("filter","original").put("brightness",0.0).put("contrast",1.0)
            val preview=render(entry,created,256)
            val image=StudioImages.load(preview.path,256)
            try {
                if(image.width<8||image.height<8)return null
                val pixels=IntArray(image.width*image.height);image.getPixels(pixels,0,image.width,0,0,image.width,image.height)
                val gray=ByteArray(pixels.size){i->val c=pixels[i];(.213*Color.red(c)+.715*Color.green(c)+.072*Color.blue(c)).toInt().toByte()}
                return ScanDetector.detect(ScanDetector.Gray(gray,image.width,image.height))?.corners
            } finally { image.recycle() }
        } finally { created.forEach{it.delete()} }
    }
    private fun render(entry: JSONObject, created: MutableList<File>, maxEdge: Int = 1800): File {
        val raw = entry.getString("original"); require(valid(raw))
        var bitmap = StudioImages.load(raw, maxEdge)
        try {
            val state = entry.getJSONObject("state"); val ops = state.getJSONArray("geometry")
            for (index in 0 until ops.length()) {
                val op = ops.getJSONObject(index)
                val next = if (op.optBoolean("rotate")) {
                    Bitmap.createBitmap(bitmap, 0, 0, bitmap.width, bitmap.height, Matrix().apply { postRotate(90f) }, true)
                } else if (op.has("quad")) {
                    val q = op.getJSONArray("quad")
                    ScanPerspective.warp(bitmap, (0..7).map { q.getDouble(it) }, maxEdge)
                } else {
                    val crop = op.getJSONArray("crop")
                    val l = (crop.getDouble(0) * bitmap.width).toInt().coerceIn(0, bitmap.width-1)
                    val t = (crop.getDouble(1) * bitmap.height).toInt().coerceIn(0, bitmap.height-1)
                    val r = (crop.getDouble(2) * bitmap.width).toInt().coerceIn(l+1, bitmap.width)
                    val b = (crop.getDouble(3) * bitmap.height).toInt().coerceIn(t+1, bitmap.height)
                    Bitmap.createBitmap(bitmap, l, t, r-l, b-t)
                }
                if (next !== bitmap) bitmap.recycle()
                bitmap = next
            }
            val filter = state.getString("filter")
            val brightness = state.optDouble("brightness", 0.0).toFloat()
            val contrast = state.optDouble("contrast", 1.0).toFloat()
            if (filter != "original" || brightness != 0f || contrast != 1f) {
                val output = Bitmap.createBitmap(bitmap.width, bitmap.height, Bitmap.Config.ARGB_8888)
                try {
                    val color = ColorMatrix()
                    if (filter == "gray" || filter == "bw") color.setSaturation(0f)
                    if (filter == "contrast" || filter == "bw" || filter == "enhance") {
                        val f = if (filter == "bw") 3.5f else if (filter == "enhance") 1.6f else 1.35f; val o = 128f * (1f-f) + if (filter == "enhance") 18f else 0f
                        color.postConcat(ColorMatrix(floatArrayOf(f,0f,0f,0f,o,0f,f,0f,0f,o,0f,0f,f,0f,o,0f,0f,0f,1f,0f)))
                    }
                    val c = contrast; val offset = 128f * (1f-c) + brightness * 128f
                    color.postConcat(ColorMatrix(floatArrayOf(c,0f,0f,0f,offset,0f,c,0f,0f,offset,0f,0f,c,0f,offset,0f,0f,0f,1f,0f)))
                    Canvas(output).drawBitmap(bitmap, 0f, 0f, Paint(Paint.ANTI_ALIAS_FLAG).apply { colorFilter = ColorMatrixColorFilter(color) })
                } catch (e: Throwable) { output.recycle(); throw e }
                bitmap.recycle(); bitmap = output
            }
            val file = File.createTempFile("page_", ".jpg", folder); created.add(file)
            write(file) { check(bitmap.compress(Bitmap.CompressFormat.JPEG, 90, it)) }
            // A filename alone never proves that a legacy page is expendable.
            val master = File(raw).canonicalFile
            if (master.name.startsWith("original_") && valid(master.path)) {
                val previous = JSONObject(prefs.getString("generatedPreviews", "{}"))
                val next = JSONObject(); val keys = previous.keys()
                while(keys.hasNext()) { val key=keys.next(); if(File(key).isFile) next.put(key,previous.getString(key)) }
                next.put(file.canonicalPath,master.path)
                check(prefs.edit().putString("generatedPreviews",next.toString()).commit()) { "Could not journal generated preview" }
            }
            return file
        } finally { bitmap.recycle() }
    }
    fun exportPdf(paths: List<String>, highQuality: Boolean, paper: String = "a4", orientation: String = "auto", margin: Int = 16, checkCancelled: () -> Unit = {}, outputDirectory: File? = null): String {
        require(paths.isNotEmpty() && paths.size <= 30 && paths.all { it in pages() })
        val edge = if (highQuality) 2600 else 1800
        // Conservative temporary-file budget; fail before touching any draft.
        require(folder.usableSpace > paths.size * 24L * 1024 * 1024) { "Free storage before exporting this scan." }
        val created = mutableListOf<File>()
        val all = records()
        try {
            val rendered = paths.map { path ->
                checkCancelled()
                val entry = all.optJSONObject(path)
                if (entry == null) path else render(entry, created, edge).path
            }
            return StudioDocumentOps(context).imagesToPdf(rendered, edge, if (highQuality) .94f else .88f, paper, orientation, margin, checkCancelled, outputDirectory)
        } finally { created.forEach { it.delete() } }
    }
    private fun archiveFolder(id: String): File {
        require(id.matches(Regex("[A-Za-z0-9_-]{1,100}"))) { "Invalid scan identifier" }
        return File(File(context.filesDir,"scan_archives").apply { mkdirs() },id)
    }
    fun archive(id: String): Boolean {
        val current=pages();require(current.isNotEmpty())
        val target=archiveFolder(id);require(!target.exists()) { "Scan already archived" }
        val staging=File(target.parentFile,"pending_"+java.util.UUID.randomUUID()).apply { check(mkdirs()) }
        val created=mutableListOf<File>()
        try {
            val all=records();val entries=JSONArray()
            for((index,path) in current.withIndex()) {
                val entry=record(path,all,created)
                val source=File(entry.getString("original"));require(valid(source.path))
                val name="original_$index.image"
                write(File(staging,name)) { out -> source.inputStream().use { it.copyTo(out) } }
                entry.put("original",name);entries.put(entry)
            }
            val manifest=JSONObject().put("version",1).put("pages",entries).toString()
            write(File(staging,"manifest.json")) { it.write(manifest.toByteArray(Charsets.UTF_8)) }
            check(staging.renameTo(target)) { "Could not preserve editable scan" }
            return true
        } catch(e:Throwable) { staging.deleteRecursively();throw e }
        finally { created.forEach { it.delete() } }
    }
    fun openArchive(id: String): List<String> {
        require(pages().isEmpty() && !prefs.contains("cameraPath") && JSONArray(prefs.getString("removedPages", "[]")).length() == 0) { "Save or clear the current scan before opening another." }
        val archive=archiveFolder(id);val manifest=File(archive,"manifest.json")
        require(manifest.isFile && manifest.length() in 1..(1024*1024)) { "Editable scan unavailable" }
        val saved=JSONObject(manifest.readText());require(saved.getInt("version")==1)
        val entries=saved.getJSONArray("pages");require(entries.length() in 1..30)
        val created=mutableListOf<File>();val next=mutableListOf<String>();val all=JSONObject()
        try {
            for(index in 0 until entries.length()) {
                val entry=copy(entries.getJSONObject(index))
                val raw=File(archive,entry.getString("original")).canonicalFile
                require(raw.parentFile==archive.canonicalFile && raw.isFile && raw.length()>0)
                entry.put("original",original(raw,created).path)
                val preview=render(entry,created);next.add(preview.path);all.put(preview.path,entry)
            }
            commit(next,all);return next
        } catch(e:Throwable) { created.forEach { it.delete() };throw e }
    }
    fun deleteArchive(id: String): Boolean {
        val target=archiveFolder(id)
        return !target.exists() || target.deleteRecursively()
    }
    fun hasPendingCapture(): Boolean = prefs.contains("cameraPath")
    /** Only stale unreferenced generated previews. Originals/camera/archive/unknown files are never swept. */
    fun cleanupGenerated(now: Long = System.currentTimeMillis()): Int {
        val keep = mutableSetOf<String>()
        val generated: JSONObject
        try {
            generated = JSONObject(prefs.getString("generatedPreviews","{}"))
            fun retain(path: String) { keep.add(File(path).canonicalPath) }
            val paths = JSONArray(prefs.getString("pages", "[]"))
            for (i in 0 until paths.length()) retain(paths.getString(i))
            val graph = records(); val keys = graph.keys()
            while (keys.hasNext()) { val key=keys.next();retain(key);retain(graph.getJSONObject(key).getString("original")) }
            val removed=JSONArray(prefs.getString("removedPages","[]"))
            for(i in 0 until removed.length()) {
                val item=removed.getJSONObject(i);retain(item.getString("path"))
                item.optJSONObject("record")?.getString("original")?.let { retain(it) }
            }
            prefs.getString("cameraPath",null)?.let { retain(it) }
        } catch(_:Exception) { return 0 }
        val cleanupRoot = folder.canonicalFile
        if (cleanupRoot.parentFile != context.filesDir.canonicalFile || cleanupRoot.name != "scan_draft") return 0
        var deleted=0
        val previewName=Regex("page_[A-Za-z0-9_-]+\\.jpg")
        cleanupRoot.listFiles()?.forEach { file ->
            val master = generated.optString(file.canonicalPath).takeIf { it.isNotEmpty() }?.let { File(it).canonicalFile }
            if(file.isFile && file.canonicalFile==file.absoluteFile && file.canonicalFile.parentFile==cleanupRoot && previewName.matches(file.name) && file.canonicalPath !in keep && master != null && master.parentFile==cleanupRoot && master.name.startsWith("original_") && master.isFile && master.length()>0 && file.lastModified()>0 && now-file.lastModified()>=24L*60*60*1000) {
                if(file.delete()) deleted++
            }
        }
        return deleted
    }
    fun beginScan() { check(prefs.edit().putBoolean("recover", true).commit()) }
    fun needsRecovery() = prefs.getBoolean("recover", false)
    fun acknowledge() { check(prefs.edit().putBoolean("recover", false).commit()) }
    fun recover(): List<String> { if (prefs.contains("cameraPath")) finishCapture(true); return pages() }
    fun clear() {
        check(prefs.edit().clear().commit())
        // Dedicated private draft directory only; gallery and exported PDFs stay intact.
        folder.listFiles()?.filter { it.isFile && it.canonicalFile.parentFile == folder.canonicalFile }?.forEach { it.delete() }
    }
}

