class StudioPdfEngine {
  static const _pdf = MethodChannel('com.hyzen.pharmd/pdf_studio');
  static const _jobKey = #studioOperation;
  static Future<T> withJob<T>(String id, Future<T> Function() action) =>
      runZoned(action, zoneValues: {_jobKey: id});
  static Map<String, dynamic> _args(Map<String, dynamic> arguments) => {
    ...arguments,
    if (Zone.current[_jobKey] case final String id) 'studioJob': id,
  };
  static Future<T?> _invoke<T>(String method, Map<String, dynamic> arguments) =>
      _pdf.invokeMethod<T>(method, _args(arguments));
  static Future<Map<K, V>?> _map<K, V>(String method, Map<String, dynamic> arguments) =>
      _pdf.invokeMapMethod<K, V>(method, _args(arguments));
  static const _files = MethodChannel('com.hyzen.pharmd/csv_files');

  static Future<List<PickedStudioFile>> pickFiles() async {
    final files = await _files.invokeListMethod<dynamic>('pickStudioFiles');
    return [
      for (final entry in files ?? const [])
        if (entry is Map && entry['name'] is String && entry['path'] is String)
          PickedStudioFile(entry['name'] as String, entry['path'] as String),
    ];
  }

  static Future<int> pageCount(String path) async =>
      await _invoke<int>('pageCount', {'path': path}) ?? 0;

  /// Page import preserves text and vectors; flatten is an explicit image export.
  static Future<String> compose(
    List<StudioPage> pages, {
    bool flatten = false,
  }) async =>
      await _invoke<String>('compose', {
        'pages': [for (final page in pages) page.toMap()],
        'flatten': flatten,
      }) ??
      '';

  static Future<String> protect(String path, String password) async =>
      await _invoke<String>('protect', {
        'path': path,
        'password': password,
      }) ??
      '';

