        'path': path,
        'preset': preset,
      }) ??
      '';

  static Future<({String path, String text})> ocr(String path) async {
    final result = await _map<String, dynamic>('ocr', {
      'path': path,
    });
    if (result == null ||
        result['path'] is! String ||
        result['text'] is! String) {
      throw const FormatException('Recognition did not finish.');
    }
    return (path: result['path'] as String, text: result['text'] as String);
  }

  static const _scanExport = MethodChannel('com.hyzen.pharmd/scan_export');
  static Future<String?> beginScanExport() => _scanExport.invokeMethod<String>('begin', {'retainFinalization': true});
  static Future<bool> finishScanExport(String id) async => await _scanExport.invokeMethod<bool>('finish', {'id': id}) ?? false;
  static Future<bool> cancelScanExport(String id) async => await _scanExport.invokeMethod<bool>('cancel', {'id': id}) ?? false;

  static Future<String> imagesToPdf(List<String> paths, {bool scanDraft = false, bool highQuality = false, String paper = 'a4', String orientation = 'auto', int margin = 16, String? exportJob}) async =>
      await _invoke<String>('imagesToPdf', {'paths': paths, 'scanDraft': scanDraft, 'highQuality': highQuality, 'paper': paper, 'orientation': orientation, 'margin': margin, if (exportJob != null) 'exportJob': exportJob}) ?? '';

  static Future<String> textToPdf(String text) async =>
      await _invoke<String>('textToPdf', {'text': text}) ?? '';

  static Future<String> textToDocx(String text) async =>
      await _invoke<String>('textToDocx', {'text': text}) ?? '';

  static Future<String> textFile(String text) async =>
      await _invoke<String>('textFile', {'text': text}) ?? '';

  static Future<String> readText(String path) async =>
      await _invoke<String>('readText', {'path': path}) ?? '';

  static Future<String> pagesToImages(String path, String format) async =>
      await _invoke<String>('pagesToImages', {
        'path': path,
        'format': format,
      }) ??
      '';

  static Future<({Uint8List bytes, int width, int height})> renderPage(
    String path,
    int index, {
    int maxEdge = 1800,
  }) async {
    final data = await _map<String, dynamic>('renderPage', {
      'path': path,
      'index': index,
      'maxEdge': maxEdge,
    });
    if (data == null || data['bytes'] is! Uint8List) {
      throw const FormatException('Page image unavailable.');
    }
    return (
      bytes: data['bytes'] as Uint8List,
      width: data['width'] as int,
      height: data['height'] as int,
    );
  }

  static Future<Map<String, List<Map<String, dynamic>>>> readAnnotations(
    String statePath,
  ) async {
    final raw =
        await _invoke<String>('getEditState', {'path': statePath}) ??
        '{}';
    final decoded = jsonDecode(raw);
    if (decoded is! Map || decoded['annotations'] is! Map) return {};
    return {
      for (final entry in (decoded['annotations'] as Map).entries)
        if (entry.key is String && entry.value is List)
          entry.key as String: [
            for (final value in entry.value as List)
              if (value is Map) Map<String, dynamic>.from(value),
          ],
    };
  }

  static Future<void> writeAnnotations(
    String statePath,
    Map<String, List<Map<String, dynamic>>> pages,
  ) async {
    final saved = await _invoke<bool>('setEditState', {
      'path': statePath,
      'json': jsonEncode({'annotations': pages}),
    });
    if (saved != true) throw PlatformException(code: 'edit_state_not_saved', message: 'The edit layer was not saved.');
  }
}

