package com.hyzen.pharmd

import android.content.Context
import android.os.SystemClock
import java.io.File
import java.util.UUID
import java.util.concurrent.CancellationException

/** Export ownership spans render + Dart's history/archive/clear finalization. */
internal object ScanExportJobs {
    private enum class Phase { PREPARED, RUNNING, FINALIZING }
    private data class Job(val id: String, val client: String?, val retained: Boolean, val preparedAt: Long,
        var phase: Phase = Phase.PREPARED, var cancelled: Boolean = false, var folder: File? = null)
    private var job: Job? = null
    private const val PREPARED_TTL_MS = 120_000L
    private const val CACHE_TTL_MS = 24L * 60 * 60 * 1000
    private val uuid = Regex("[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}")

    @Synchronized fun begin(client: String? = null, retain: Boolean = false, now: Long = SystemClock.elapsedRealtime()): String {
        val previous = job
        if (previous != null && previous.phase == Phase.PREPARED && now - previous.preparedAt >= PREPARED_TTL_MS) job = null
        kotlin.check(job == null) { "Another scan export is running. Finish it first." }
        return UUID.randomUUID().toString().also { job = Job(it, client, retain, now) }
    }
    @Synchronized fun cancel(id: String): Boolean {
        val current = job ?: return false
        if (current.id != id || current.phase == Phase.FINALIZING) return false
        current.cancelled = true; return true
    }
    @Synchronized fun check(id: String?) {
        kotlin.check(job?.id == id) { "Scan export session unavailable." }
        if (job?.cancelled == true) throw CancellationException("Export cancelled. Draft retained.")
    }
    @Synchronized fun start(id: String) { check(id); kotlin.check(job!!.phase == Phase.PREPARED) { "Export has already started." }; job!!.phase = Phase.RUNNING }
    @Synchronized fun requireDraftAccess(id: String? = null, action: String = "") {
        val current = job ?: return
        kotlin.check(current.phase == Phase.FINALIZING && current.id == id && action in setOf("archive", "clear")) {
            "Finish or cancel the PDF export before changing this draft."
        }
    }
    @Synchronized fun outputDirectory(context: Context, id: String): File {
        check(id)
        val root = File(context.cacheDir.canonicalFile,"scan_exports").apply { mkdirs() }
        kotlin.check(root.canonicalFile == root.absoluteFile)
        val folder = File(root,id).apply { mkdirs() }
        kotlin.check(folder.canonicalFile.parentFile == root.canonicalFile && folder.canonicalFile == folder.absoluteFile)
        job!!.folder = folder
        return folder
    }
    @Synchronized fun complete(id: String?, path: String): String {
        try { check(id) } catch (e: Exception) { File(path).delete(); throw e }
        val current = job
        if (current?.retained == true) current.phase = Phase.FINALIZING else job = null
        return path
    }
    @Synchronized fun endRendering(id: String) {
        val current = job ?: return
        if (current.id == id && current.phase != Phase.FINALIZING) { job = null; deleteGenerated(current.folder) }
    }
    @Synchronized fun finish(id: String): Boolean {
        val current = job ?: return false
        if (current.id != id || current.phase == Phase.RUNNING) return false
        job = null; deleteGenerated(current.folder); return true
    }
    /** Test/failed-operation release. Never releases another export's ownership. */
    @Synchronized fun release(id: String?) { if (job?.id == id) { val folder=job?.folder; job=null; deleteGenerated(folder) } }
    @Synchronized fun abandon(client: String) {
        val current = job ?: return
        if (current.client != client) return
        if (current.phase == Phase.RUNNING) current.cancelled = true
        else job = null // Finished output gets the conservative cache grace period.
    }
    private fun deleteGenerated(folder: File?): Int {
        if (folder == null || folder.canonicalFile != folder.absoluteFile || !uuid.matches(folder.name)) return 0
        val files = folder.listFiles() ?: return 0
        if (files.any { !it.isFile || it.canonicalFile != it.absoluteFile || !it.name.startsWith("hyzen_document_") || it.extension != "pdf" }) return 0
        var count = 0
        files.forEach { if (it.delete()) count++ }
        folder.delete(); return count
    }
    @Synchronized fun cleanupGenerated(context: Context, now: Long = System.currentTimeMillis()): Int {
        val root = File(context.cacheDir.canonicalFile,"scan_exports")
        if (root.canonicalFile != root.absoluteFile) return 0
        var deleted = 0
        root.listFiles()?.forEach { folder ->
            if (folder.isDirectory && folder.canonicalFile == folder.absoluteFile && folder.canonicalFile.parentFile == root.canonicalFile && uuid.matches(folder.name) && folder != job?.folder) {
                val files = folder.listFiles() ?: return@forEach
                if (folder.lastModified() > 0 && now - folder.lastModified() >= CACHE_TTL_MS && files.all { it.lastModified() > 0 && now - it.lastModified() >= CACHE_TTL_MS }) deleted += deleteGenerated(folder)
            }
        }
        return deleted
    }
}

