package com.hyzen.pharmd

import android.graphics.Bitmap
import android.graphics.Color
import android.content.pm.PackageManager
import androidx.test.ext.junit.runners.AndroidJUnit4
import androidx.test.platform.app.InstrumentationRegistry
import org.junit.Assert.*
import org.junit.Before
import org.junit.After
import org.junit.Test
import org.junit.runner.RunWith
import java.io.File

@RunWith(AndroidJUnit4::class)
class ScanDraftStoreTest {
    private val context get() = InstrumentationRegistry.getInstrumentation().targetContext
    @Before fun reset() { ScanDraftStore(context).clear() }
    @After fun clear() { ScanDraftStore(context).clear() }
    private fun image(file: File, color: Int = Color.WHITE) {
        val bitmap = Bitmap.createBitmap(500, 700, Bitmap.Config.ARGB_8888)
        bitmap.eraseColor(color)
        file.outputStream().use { bitmap.compress(Bitmap.CompressFormat.JPEG, 88, it) }
        bitmap.recycle()
    }
    @Test fun exportLeaseCancellationAndCompletionAreExclusive() {
        val id=ScanExportJobs.begin()
        val partial=File.createTempFile("cancelled_export_", ".pdf",context.cacheDir)
        try {
            assertFalse(ScanExportJobs.cancel("another-job"))
            try { ScanExportJobs.begin();fail("Only one cancellable export") } catch(_:IllegalStateException) {}
            assertTrue(ScanExportJobs.cancel(id))
            try { ScanExportJobs.complete(id,partial.path);fail("Cancelled output must not escape") } catch(_:java.util.concurrent.CancellationException) {}
            assertFalse(partial.exists())
        } finally { ScanExportJobs.release(id);partial.delete() }
        val next=ScanExportJobs.begin();val finished=File.createTempFile("finished_export_", ".pdf",context.cacheDir)
        try { assertEquals(finished.path,ScanExportJobs.complete(next,finished.path));assertFalse(ScanExportJobs.cancel(next));assertTrue(finished.exists()) }
        finally { ScanExportJobs.release(next);finished.delete() }
    }
    @Test fun cancellingDuringScanRenderKeepsDraftAndCleansTemporaryPages() {
        val store=ScanDraftStore(context)
        image(store.newCapture());store.finishCapture(true)
        image(store.newCapture(),Color.BLUE);val before=store.finishCapture(true)
