    @Test fun sharedQueueIsFifoAndNeverOverlapsAcrossCallers() {
        assertSame(ScanWork.executor,NativeDocumentWork.executor)
        val order=Collections.synchronizedList(mutableListOf<Int>());val active=AtomicInteger();val peak=AtomicInteger();val done=CountDownLatch(40)
        repeat(40){i->NativeDocumentWork.executor.execute{try{val count=active.incrementAndGet();peak.updateAndGet{old->maxOf(old,count)};order.add(i)}finally{active.decrementAndGet();done.countDown()}}}
        assertTrue(done.await(20,TimeUnit.SECONDS));assertEquals(1,peak.get());assertEquals((0 until 40).toList(),order)
    }
    @Test fun onlyUnstartedPreparationExpiresAndOldTicketsCannotTakeOver() {
