package com.hyzen.pharmd

import android.content.Context
import android.os.SystemClock
import java.io.File
import java.util.UUID
import java.util.concurrent.CancellationException

/** Per-client cooperative export sessions. Only this session's generated files are reclaimed. */
internal object StudioWorkJobs {
    private enum class Phase { PREPARED, READY, RUNNING, FINALIZING }
    private data class Job(val client: String, val created: Long, var phase: Phase = Phase.PREPARED,
        var cancelled: Boolean = false, var abandoned: Boolean = false, var folder: File? = null)
    private val jobs = mutableMapOf<String, Job>()
    private const val DAY = 24L * 60 * 60 * 1000
    private val uuid = Regex("[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}[a-f0-9]{8}")
    @Synchronized fun begin(client: String, now: Long = SystemClock.elapsedRealtime()): String {
        // Only unstarted sessions expire; between-step work and saving retain ownership.
        jobs.entries.removeAll { (_, job) ->
            if (job.phase == Phase.PREPARED && now - job.created >= 120_000) { clean(job.folder); true } else false
        }
        check(jobs.size < 4) { "Finish the current document operations first." }
        return UUID.randomUUID().toString().also { jobs[it] = Job(client, now) }
    }
    private fun owned(id: String, client: String): Job = jobs[id]?.takeIf { it.client == client }
        ?: error("Document operation is unavailable. Retry from your original document.")
    @Synchronized fun check(id: String, client: String) {
        val job = owned(id, client)
        if (job.cancelled) throw CancellationException("Operation cancelled. Original retained.")
    }
    @Synchronized fun start(id: String, client: String) {
        check(id, client); val job = owned(id, client)
        check(job.phase in setOf(Phase.PREPARED, Phase.READY)) { "Document operation is already running or saving." }
        job.phase = Phase.RUNNING
    }
    @Synchronized fun end(id: String, client: String) {
        val job = owned(id, client)
        if (job.abandoned) { jobs.remove(id); clean(job.folder) }
        else if (job.phase == Phase.RUNNING) job.phase = Phase.READY
    }
    @Synchronized fun cancel(id: String, client: String): Boolean {
        val job = jobs[id]?.takeIf { it.client == client } ?: return false
        if (job.phase == Phase.FINALIZING) return false
        job.cancelled = true; return true
    }
    @Synchronized fun commit(id: String, client: String): Boolean {
        check(id, client); val job = owned(id, client)
        check(job.phase in setOf(Phase.PREPARED, Phase.READY)) { "Wait for document processing to finish." }
        job.phase = Phase.FINALIZING; return true
    }
    @Synchronized fun finish(id: String, client: String): Boolean {
        val job = jobs[id]?.takeIf { it.client == client } ?: return false
        if (job.phase == Phase.RUNNING) { job.cancelled = true; job.abandoned = true; return false }
        jobs.remove(id); clean(job.folder); return true
    }
    @Synchronized fun abandon(client: String) {
        jobs.filterValues { it.client == client }.keys.toList().forEach { id ->
            val job = jobs.getValue(id)
            if (job.phase == Phase.RUNNING) { job.cancelled = true; job.abandoned = true }
            else { jobs.remove(id) } // Completed outputs retain the conservative cache grace period.
        }
    }
    @Synchronized fun directory(context: Context, id: String, client: String): File {
        check(id, client)
        val root = File(context.cacheDir.canonicalFile, "studio_operations").apply { mkdirs() }
        check(root.canonicalFile == root.absoluteFile)
        val folder = File(root, id).apply { mkdirs() }
        check(folder.canonicalFile == folder.absoluteFile && folder.parentFile == root)
        owned(id, client).folder = folder; return folder
    }
    private fun clean(folder: File?): Int {
        if (folder == null || folder.canonicalFile != folder.absoluteFile || !uuid.matches(folder.name)) return 0
        val files = folder.listFiles() ?: return 0
        if (files.any { !it.isFile || it.canonicalFile != it.absoluteFile ||
            !it.name.matches(Regex("(?:hyzen_document_|hyzen_rich_|studio_)[A-Za-z0-9_]+\\.(?:pdf|docx|txt|zip)")) }) return 0
        var count = 0; files.forEach { if (it.delete()) count++ }; folder.delete(); return count
    }
    @Synchronized fun cleanup(context: Context, now: Long = System.currentTimeMillis()): Int {
        val root = File(context.cacheDir.canonicalFile, "studio_operations")
        if (root.canonicalFile != root.absoluteFile) return 0
        var count = 0
        root.listFiles()?.forEach { folder ->
            if (folder.isDirectory && folder.canonicalFile == folder.absoluteFile && uuid.matches(folder.name) &&
                jobs.values.none { it.folder == folder } && folder.lastModified() > 0 && now-folder.lastModified() >= DAY &&
                folder.listFiles()?.all { it.lastModified() > 0 && now-it.lastModified() >= DAY } == true) count += clean(folder)
        }; return count
    }
}

package com.hyzen.pharmd

import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.graphics.Canvas
import android.graphics.Color
import android.graphics.Matrix
import android.graphics.Paint
import android.graphics.Path
import android.graphics.RectF
import android.graphics.Typeface
import android.graphics.pdf.PdfDocument
import android.graphics.pdf.PdfRenderer
import android.os.ParcelFileDescriptor
import java.io.File
import java.io.ByteArrayOutputStream
import java.util.zip.ZipEntry
import java.util.zip.ZipOutputStream

/** New-file raster/ZIP/text exporters with cooperative cancellation boundaries. */
internal class StudioExportFormats(private val activity: android.content.Context) {
    private fun output(directory: File? = null): File = File.createTempFile("studio_", ".pdf", directory ?: activity.cacheDir)

    fun compose(pages: List<Map<String, Any?>>, checkpoint: () -> Unit = {}, directory: File? = null): String {
        require(pages.isNotEmpty() && pages.size <= 150) { "Select 1–150 pages." }
        val destination = output(directory)
        val document = PdfDocument()
        val inputs = mutableMapOf<String, Pair<ParcelFileDescriptor, PdfRenderer>>()
        try {
            pages.forEachIndexed { position, spec ->
                checkpoint()
                if (spec["blank"] == true) {
                    val blank = document.startPage(PdfDocument.PageInfo.Builder(595, 842, position + 1).create())
                    blank.canvas.drawColor(Color.WHITE)
                    document.finishPage(blank)
                    return@forEachIndexed
                }
                val source = File(spec["path"] as? String ?: error("Missing source"))
                val index = (spec["page"] as? Number)?.toInt() ?: error("Missing page index")
                val rotation = ((spec["rotation"] as? Number)?.toInt() ?: 0).rem(360)
                require(rotation == 0 || rotation == 90 || rotation == 180 || rotation == 270) { "Invalid rotation" }
                val renderer = inputs.getOrPut(source.canonicalPath) {
                    val fd = ParcelFileDescriptor.open(source, ParcelFileDescriptor.MODE_READ_ONLY)
                    try { fd to PdfRenderer(fd) }
                    catch (e: Throwable) { fd.close(); throw e }
                }.second
                        require(index in 0 until renderer.pageCount) { "Page out of range" }
                        renderer.openPage(index).use { page ->
                            val sideways = rotation == 90 || rotation == 270
                            val width = if (sideways) page.height else page.width
                            val height = if (sideways) page.width else page.height
                            val scale = minOf(2f, 2000f / maxOf(page.width, page.height))
                            val bitmap = Bitmap.createBitmap(
                                maxOf(1, (page.width * scale).toInt()),
                                maxOf(1, (page.height * scale).toInt()), Bitmap.Config.ARGB_8888
                            )
                            try {
                                bitmap.eraseColor(Color.WHITE)
                                page.render(bitmap, null, null, PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY)
                                val info = PdfDocument.PageInfo.Builder(width, height, position + 1).create()
                                val target = document.startPage(info)
                                val canvas = target.canvas
                                canvas.drawColor(Color.WHITE)
                                canvas.save()
                                when (rotation) {
                                    90 -> { canvas.translate(width.toFloat(), 0f); canvas.rotate(90f) }
                                    180 -> { canvas.translate(width.toFloat(), height.toFloat()); canvas.rotate(180f) }
                                    270 -> { canvas.translate(0f, height.toFloat()); canvas.rotate(270f) }
                                }
                                canvas.drawBitmap(bitmap, null, RectF(0f, 0f, page.width.toFloat(), page.height.toFloat()), Paint(Paint.FILTER_BITMAP_FLAG))
                                canvas.restore()
                                @Suppress("UNCHECKED_CAST")
                                val marks = spec["annotations"] as? List<Map<String, Any?>> ?: emptyList()
                                paintAnnotations(canvas, marks, width.toFloat(), height.toFloat())
                                document.finishPage(target)
                            } finally { bitmap.recycle() }
                        }
            }
            checkpoint()
            destination.outputStream().use { document.writeTo(it) }
            checkpoint()
            return destination.absolutePath
        } catch (e: Throwable) {
            destination.delete()
            throw e
        } finally {
            document.close()
            inputs.values.forEach { (fd, renderer) ->
                try { renderer.close() } finally { fd.close() }
            }
        }
    }

    fun textToPdf(text: String, checkpoint: () -> Unit = {}, directory: File? = null): String {
        require(text.length <= 200_000) { "Document is too long." }
        val destination = output(directory)
        val document = PdfDocument()
        val paint = Paint(Paint.ANTI_ALIAS_FLAG).apply { color = Color.BLACK; textSize = 12f }
        try {
            val lines = mutableListOf<String>()
            text.replace("\r\n", "\n").split('\n').forEach { paragraph ->
                checkpoint()
                var line = ""
                paragraph.split(' ').forEach { word ->
                    val next = if (line.isEmpty()) word else "$line $word"
                    if (paint.measureText(next) > 510f && line.isNotEmpty()) { lines.add(line); line = word }
                    else line = next
                }
                lines.add(line)
            }
            require(lines.size <= 5000) { "Document is too long." }
            lines.chunked(48).forEachIndexed { i, chunk ->
                checkpoint()
                val page = document.startPage(PdfDocument.PageInfo.Builder(595, 842, i + 1).create())
                page.canvas.drawColor(Color.WHITE)
                chunk.forEachIndexed { row, line -> page.canvas.drawText(line.take(400), 42f, 48f + row * 16f, paint) }
                document.finishPage(page)
            }
            checkpoint()
            destination.outputStream().use { document.writeTo(it) }
            checkpoint()
            return destination.absolutePath
        } catch (e: Throwable) { destination.delete(); throw e }
        finally { document.close() }
    }

    fun textToDocx(text: String, checkpoint: () -> Unit = {}, directory: File? = null): String {
        require(text.length <= 200_000) { "Document is too long." }
        val destination = File.createTempFile("studio_document_", ".docx", directory ?: activity.cacheDir)
        fun escape(value: String): String = value.replace("&", "&amp;")
            .replace("<", "&lt;").replace(">", "&gt;")
            .replace("\"", "&quot;").replace("'", "&apos;")
        val paragraphs = text.replace("\r\n", "\n").split('\n').joinToString("") { line ->
            "<w:p><w:r><w:t xml:space=\"preserve\">${escape(line.filter { it == '\t' || it >= ' ' })}</w:t></w:r></w:p>"
        }
        try {
            ZipOutputStream(destination.outputStream().buffered()).use { zip ->
                fun entry(name: String, xml: String) {
                    checkpoint()
                    zip.putNextEntry(ZipEntry(name))
                    zip.write(xml.toByteArray(Charsets.UTF_8))
                    zip.closeEntry()
                }
                entry("[Content_Types].xml", """<?xml version="1.0" encoding="UTF-8"?>
                    <Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">
                    <Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>
                    <Default Extension="xml" ContentType="application/xml"/>
                    <Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/>
                    </Types>""".trimIndent())
                entry("_rels/.rels", """<?xml version="1.0" encoding="UTF-8"?>
                    <Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
                    <Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/>
                    </Relationships>""".trimIndent())
                entry("word/document.xml", """<?xml version="1.0" encoding="UTF-8"?>
                    <w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main">
                    <w:body>$paragraphs<w:sectPr/></w:body></w:document>""".trimIndent())
            }
            checkpoint()
            return destination.absolutePath
        } catch (e: Throwable) { destination.delete(); throw e }
    }

    fun pagesToImages(path: String, format: String, checkpoint: () -> Unit = {}, directory: File? = null): String {
        require(format == "png" || format == "jpg") { "Choose PNG or JPG." }
        val archive = File.createTempFile("studio_pages_", ".zip", directory ?: activity.cacheDir)
        try {
            ParcelFileDescriptor.open(File(path), ParcelFileDescriptor.MODE_READ_ONLY).use { fd ->
                PdfRenderer(fd).use { renderer ->
                    require(renderer.pageCount <= 150) { "Export up to 150 pages." }
                    ZipOutputStream(archive.outputStream().buffered()).use { zip ->
                        for (index in 0 until renderer.pageCount) {
                            checkpoint()
                            renderer.openPage(index).use { page ->
                                val factor = minOf(2f, 2000f / maxOf(page.width, page.height))
                                val bitmap = Bitmap.createBitmap(
                                    maxOf(1, (page.width * factor).toInt()),
                                    maxOf(1, (page.height * factor).toInt()), Bitmap.Config.ARGB_8888
                                )
                                try {
                                    bitmap.eraseColor(Color.WHITE)
                                    page.render(bitmap, null, null, PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY)
                                    zip.putNextEntry(ZipEntry("page_${(index + 1).toString().padStart(3, '0')}.$format"))
                                    bitmap.compress(if (format == "png") Bitmap.CompressFormat.PNG else Bitmap.CompressFormat.JPEG, 85, zip)
                                    zip.closeEntry()
                                } finally { bitmap.recycle() }
                            }
                        }
                    }
                }
            }
            checkpoint()
            return archive.absolutePath
        } catch (e: Throwable) { archive.delete(); throw e }
    }

    private fun paintAnnotations(canvas: Canvas, marks: List<Map<String, Any?>>, width: Float, height: Float) {
        for (mark in marks.take(200)) {
            val type = mark["tool"] as? String ?: continue
            val raw = mark["points"] as? List<*> ?: continue
            val points = raw.mapNotNull { pair ->
                val values = pair as? List<*> ?: return@mapNotNull null
                if (values.size != 2) return@mapNotNull null
                val x = (values[0] as? Number)?.toFloat() ?: return@mapNotNull null
                val y = (values[1] as? Number)?.toFloat() ?: return@mapNotNull null
                if (!x.isFinite() || !y.isFinite()) return@mapNotNull null
                (x.coerceIn(0f, 1f) * width) to (y.coerceIn(0f, 1f) * height)
            }
            if (points.isEmpty()) continue
            val color = (mark["color"] as? Number)?.toInt() ?: Color.rgb(103, 49, 210)
            val stroke = ((mark["stroke"] as? Number)?.toFloat() ?: 3f).coerceIn(1f, 32f)
            val paint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
                this.color = color
                val opacity = (mark["opacity"] as? Number)?.toFloat()?.takeIf { it.isFinite() }
                alpha = if (opacity != null) (opacity.coerceIn(0f,1f)*255).toInt() else if (type == "highlight") 102 else Color.alpha(color)
                style = Paint.Style.STROKE
                strokeWidth = if (type == "highlight") stroke * 5f else stroke
                strokeCap = Paint.Cap.ROUND
                strokeJoin = Paint.Join.ROUND
            }
            val first = points.first()
            val last = points.last()
            when (type) {
                "ink", "highlight", "underline", "strike", "arrow" -> {
                    val line = Path().apply {
                        moveTo(first.first, first.second)
                        points.drop(1).forEach { lineTo(it.first, it.second) }
                    }
                    canvas.drawPath(line, paint)
                    if(type=="arrow") {
                        val angle=kotlin.math.atan2(last.second-first.second,last.first-first.first)
                        val head=maxOf(10f,stroke*4)
                        canvas.drawLine(last.first,last.second,last.first-head*kotlin.math.cos(angle-.5f),last.second-head*kotlin.math.sin(angle-.5f),paint)
                        canvas.drawLine(last.first,last.second,last.first-head*kotlin.math.cos(angle+.5f),last.second-head*kotlin.math.sin(angle+.5f),paint)
                    }
                }
                "rectangle" -> canvas.drawRect(minOf(first.first, last.first), minOf(first.second, last.second),
                    maxOf(first.first, last.first), maxOf(first.second, last.second), paint)
                "circle" -> canvas.drawOval(RectF(minOf(first.first, last.first), minOf(first.second, last.second),
                    maxOf(first.first, last.first), maxOf(first.second, last.second)), paint)
                "text", "signature", "note" -> {
                    val label = (mark["text"] as? String ?: "").take(90)
                    paint.style = Paint.Style.FILL
                    paint.textSize = if (type == "signature") 24f else 14f
                    if (type == "signature") paint.typeface = Typeface.create(Typeface.SERIF, Typeface.ITALIC)
                    canvas.drawText(label, first.first, first.second + paint.textSize, paint)
                }
            }
        }
    }

}

package com.hyzen.pharmd

import android.content.Context
import android.graphics.*
import android.graphics.pdf.PdfDocument
import java.io.File
import java.io.ByteArrayOutputStream
import java.util.zip.ZipEntry
import java.util.zip.ZipOutputStream

/** Structured new documents: paragraphs, headings, lists, tables and images. */
class StudioRichWriter(private val context: Context, private val outputDirectory: File? = null, private val checkpoint: () -> Unit = {}) {
    fun write(blocks: List<Map<String,Any?>>, format: String): String {
        require(blocks.isNotEmpty() && blocks.size<=100)
        require(blocks.sumOf{(it["text"] as? String ?: "").length}<=200_000)
        return if(format=="docx") docx(blocks) else pdf(blocks)
    }
    private fun image(path:String):Bitmap = StudioImages.load(path,1600)
    private fun pdf(blocks:List<Map<String,Any?>>):String {
        val output=File.createTempFile("hyzen_rich_",".pdf",outputDirectory ?: context.cacheDir)
        val doc=PdfDocument();var number=1
        var page=doc.startPage(PdfDocument.PageInfo.Builder(595,842,number).create())
        var y=48f
        fun space(height:Float) {checkpoint();if(y+height>800){doc.finishPage(page);number++;page=doc.startPage(PdfDocument.PageInfo.Builder(595,842,number).create());y=48f;require(number<=150)}}
        try {
            for(block in blocks) {
                checkpoint()
                val type=block["type"] as? String ?: "paragraph"
                if(type=="image") {
                    val bitmap=image(block["path"] as String)
                    try {val scale=minOf(500f/bitmap.width,330f/bitmap.height);val w=bitmap.width*scale;val h=bitmap.height*scale
                        space(h+16);page.canvas.drawBitmap(bitmap,null,RectF(48f,y,48f+w,y+h),Paint(Paint.FILTER_BITMAP_FLAG));y+=h+16
                    }finally{bitmap.recycle()};continue
                }
                val text=(block["text"] as? String ?: "").replace("\r","")
                val bold=block["bold"]==true || type=="heading"
                val italic=block["italic"]==true
                val paint=Paint(Paint.ANTI_ALIAS_FLAG).apply {
                    color=Color.rgb(25,22,40);textSize=if(type=="heading")22f else 12f
                    typeface=Typeface.create(Typeface.SANS_SERIF,(if(bold)Typeface.BOLD else 0) or (if(italic)Typeface.ITALIC else 0))
                    isUnderlineText=block["underline"]==true
                }
                if(type=="table") {
                    val rows=text.lines().filter{it.isNotBlank()}.take(50).map{it.split('|').take(6)}
                    val columns=rows.maxOfOrNull{it.size} ?: 1
                    val width=500f/columns
                    val border=Paint().apply{color=Color.LTGRAY;style=Paint.Style.STROKE;strokeWidth=1f}
                    for(row in rows){space(30f);for(col in 0 until columns){val x=48+col*width
                        page.canvas.drawRect(x,y,x+width,y+27,border)
                        var label=row.getOrNull(col) ?: "";while(paint.measureText(label)>width-8 && label.isNotEmpty())label=label.dropLast(1)
                        page.canvas.drawText(label,x+4,y+18,paint)};y+=27f};y+=12;continue
                }
                for(raw in text.lines()) {
                    checkpoint()
                    val paragraph=if(type=="list") "• $raw" else raw
                    val lines=mutableListOf<String>();var line=""
                    for(word in paragraph.split(' ')) {
                        checkpoint()
                        var token=word
                        if(paint.measureText(if(line.isEmpty())token else "$line $token")>500 && line.isNotEmpty()){lines.add(line);line=""}
                        while(paint.measureText(token)>500 && token.length>1){var end=token.length-1;while(end>1 && paint.measureText(token.take(end))>500)end--;lines.add(token.take(end));token=token.drop(end)}
                        line=if(line.isEmpty())token else "$line $token"
                    };lines.add(line)
                    for(value in lines){val height=paint.textSize*1.5f;space(height)
                        val x=when(block["align"]){"center"->48+(500-paint.measureText(value))/2;"right"->548-paint.measureText(value);else->48f}
                        page.canvas.drawText(value,x,y+paint.textSize,paint);y+=height
                    }
                };y+=10
            }
            doc.finishPage(page);checkpoint();output.outputStream().use{doc.writeTo(it)};checkpoint();return output.absolutePath
        }catch(e:Throwable){output.delete();try{doc.finishPage(page)}catch(_:Exception){};throw e}finally{doc.close()}
    }
    private fun xml(s:String)=s.filter{it=='\n'||it=='\t'||it>=' '}.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;")
    private fun docx(blocks:List<Map<String,Any?>>):String {
        val output=File.createTempFile("hyzen_rich_",".docx",outputDirectory ?: context.cacheDir)
        val relationships=StringBuilder();val body=StringBuilder();var imageNumber=0
        try {ZipOutputStream(output.outputStream().buffered()).use { zip ->
            fun bytes(name:String,data:ByteArray){checkpoint();zip.putNextEntry(ZipEntry(name));zip.write(data);zip.closeEntry()}
            fun entry(name:String,text:String)=bytes(name,text.toByteArray(Charsets.UTF_8))
            fun paragraph(text:String,block:Map<String,Any?>):String {
                val style=buildString {if(block["bold"]==true || block["type"]=="heading")append("<w:b/>");if(block["italic"]==true)append("<w:i/>");if(block["underline"]==true)append("<w:u w:val=\"single\"/>");append("<w:sz w:val=\"${if(block["type"]=="heading")36 else 24}\"/>")}
                val align=if(block["align"] in listOf("center","right"))block["align"] else "left"
                return "<w:p><w:pPr><w:jc w:val=\"$align\"/></w:pPr><w:r><w:rPr>$style</w:rPr><w:t xml:space=\"preserve\">${xml(text)}</w:t></w:r></w:p>"
            }
            for(block in blocks) {
                checkpoint()
                val type=block["type"] ?: "paragraph";val text=block["text"] as? String ?: ""
                when(type) {
                    "image"->{imageNumber++;val bitmap=image(block["path"] as String)
                        try {val buffer=ByteArrayOutputStream();bitmap.compress(Bitmap.CompressFormat.PNG,100,buffer);bytes("word/media/image$imageNumber.png",buffer.toByteArray())
                            val cx=4572000L;val cy=cx*bitmap.height/bitmap.width
                            relationships.append("<Relationship Id=\"rId$imageNumber\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/image\" Target=\"media/image$imageNumber.png\"/>")
                            body.append("""<w:p><w:r><w:drawing><wp:inline><wp:extent cx="$cx" cy="$cy"/><wp:docPr id="$imageNumber" name="Image $imageNumber"/><a:graphic><a:graphicData uri="http://schemas.openxmlformats.org/drawingml/2006/picture"><pic:pic><pic:nvPicPr><pic:cNvPr id="$imageNumber" name="Image"/><pic:cNvPicPr/></pic:nvPicPr><pic:blipFill><a:blip r:embed="rId$imageNumber"/><a:stretch><a:fillRect/></a:stretch></pic:blipFill><pic:spPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="$cx" cy="$cy"/></a:xfrm><a:prstGeom prst="rect"><a:avLst/></a:prstGeom></pic:spPr></pic:pic></a:graphicData></a:graphic></wp:inline></w:drawing></w:r></w:p>""")
                        }finally{bitmap.recycle()}}
                    "table"->{body.append("<w:tbl><w:tblPr><w:tblBorders><w:top w:val=\"single\"/><w:left w:val=\"single\"/><w:bottom w:val=\"single\"/><w:right w:val=\"single\"/><w:insideH w:val=\"single\"/><w:insideV w:val=\"single\"/></w:tblBorders></w:tblPr>")
                        for(row in text.lines().filter{it.isNotBlank()}.take(50)){body.append("<w:tr>");for(cell in row.split('|').take(6))body.append("<w:tc>${paragraph(cell,block)}</w:tc>");body.append("</w:tr>")};body.append("</w:tbl>")}
                    else->for(line in text.lines())body.append(paragraph(if(type=="list")"• $line" else line,block))
                }
            }
            entry("[Content_Types].xml","""<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Default Extension="png" ContentType="image/png"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/></Types>""")
            entry("_rels/.rels","""<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rIdDoc" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>""")
            entry("word/_rels/document.xml.rels","""<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">$relationships</Relationships>""")
            entry("word/document.xml","""<?xml version="1.0" encoding="UTF-8"?><w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" xmlns:wp="http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing" xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" xmlns:pic="http://schemas.openxmlformats.org/drawingml/2006/picture"><w:body>$body<w:sectPr><w:pgSz w:w="11906" w:h="16838"/></w:sectPr></w:body></w:document>""")
        };checkpoint();return output.absolutePath}catch(e:Throwable){output.delete();throw e}
