package com.hyzen.pharmd

import androidx.test.ext.junit.runners.AndroidJUnit4
import androidx.test.platform.app.InstrumentationRegistry
import com.tom_roush.pdfbox.android.PDFBoxResourceLoader
import com.tom_roush.pdfbox.pdmodel.PDDocument
import com.tom_roush.pdfbox.pdmodel.PDPage
import org.junit.Assert.*
import org.junit.Before
import org.junit.Test
import org.junit.runner.RunWith
import java.io.File
import java.util.UUID
import java.util.concurrent.CancellationException
import java.util.concurrent.CountDownLatch
import java.util.concurrent.Executors

@RunWith(AndroidJUnit4::class)
class StudioWorkJobsTest {
    private val context get() = InstrumentationRegistry.getInstrumentation().targetContext
    @Before fun resources() { PDFBoxResourceLoader.init(context) }
    private fun source(): File = File.createTempFile("work_original_", ".pdf", context.cacheDir).also { file ->
        PDDocument().use { doc -> repeat(3) { doc.addPage(PDPage()) }; doc.save(file) }
    }
    private fun cancelled(action: () -> Unit) {
        try { action(); fail("Expected cancellation") } catch (_: CancellationException) { }
    }
    private fun rejected(action: () -> Unit) {
        try { action(); fail("Expected rejected state") } catch (_: IllegalStateException) { }
    }
    @Test fun queuedCancellationAndClientIsolationRejectReplayWithoutTouchingOriginals() {
        val client=UUID.randomUUID().toString(); val id=StudioWorkJobs.begin(client)
        try {
            assertFalse(StudioWorkJobs.cancel(id,"other")); rejected { StudioWorkJobs.start(id,"other") }
            assertTrue(StudioWorkJobs.cancel(id,client)); cancelled { StudioWorkJobs.start(id,client) }
            cancelled { StudioWorkJobs.commit(id,client) }
        } finally { assertTrue(StudioWorkJobs.finish(id,client)) }
        rejected { StudioWorkJobs.start(id,client) }
    }
    @Test fun commitAndCancelArbitrateAtomicallyAndNeverReportBothSuccess() {
        val pool=Executors.newFixedThreadPool(2)
        try { repeat(40) {
            val client="race-$it";val id=StudioWorkJobs.begin(client);val gate=CountDownLatch(1)
            val save=pool.submit<Boolean> { gate.await();try { StudioWorkJobs.commit(id,client) }catch(_:CancellationException){false} }
            val cancel=pool.submit<Boolean> { gate.await();StudioWorkJobs.cancel(id,client) };gate.countDown()
            val saved=save.get();val stopped=cancel.get();assertTrue(saved xor stopped)
            if(saved) assertFalse(StudioWorkJobs.cancel(id,client)) else cancelled { StudioWorkJobs.check(id,client) }
            StudioWorkJobs.finish(id,client)
        }} finally { pool.shutdownNow() }
    }
    @Test fun runningSessionCannotExpireAndAbandonWaitsForWorkerToReleaseItsOwnFiles() {
        val client="lifecycle";val id=StudioWorkJobs.begin(client,0);val original=source();val before=original.readBytes()
        val folder=StudioWorkJobs.directory(context,id,client);val generated=File(folder,"studio_partial.pdf").apply{writeText("partial")}
        try {
            StudioWorkJobs.start(id,client)
            val other=StudioWorkJobs.begin("other",999999);StudioWorkJobs.finish(other,"other")
            StudioWorkJobs.check(id,client);StudioWorkJobs.abandon("unrelated");assertTrue(generated.exists())
            StudioWorkJobs.abandon(client);assertTrue(generated.exists());cancelled { StudioWorkJobs.check(id,client) }
            StudioWorkJobs.end(id,client);assertFalse(generated.exists());assertArrayEquals(before,original.readBytes())
        }finally { StudioWorkJobs.finish(id,client);original.delete() }
    }
    @Test fun cleanupKeepsActiveRecentUnknownAndSymlinkFiles() {
        val root=File(context.cacheDir.canonicalFile,"studio_operations").apply{mkdirs()};val old=System.currentTimeMillis()-48L*3600*1000
        fun folder()=File(root,UUID.randomUUID().toString()).apply{mkdirs()}
        fun file(folder:File,name:String)=File(folder,name).apply{writeText("fixture");setLastModified(old);folder.setLastModified(old)}
        val stale=folder();val staleFile=file(stale,"studio_partial.pdf")
        val unknown=folder();val unknownFile=file(unknown,"user_original.pdf")
        val recent=folder();val recentFile=File(recent,"studio_recent.pdf").apply{writeText("recent")}
        val external=File.createTempFile("source_",".pdf",context.cacheDir);val linked=folder();val link=File(linked,"studio_link.pdf")
        android.system.Os.symlink(external.path,link.path);linked.setLastModified(old)
        val id=StudioWorkJobs.begin("active");val active=StudioWorkJobs.directory(context,id,"active");val activeFile=file(active,"studio_active.pdf")
        try {
            StudioWorkJobs.cleanup(context);assertFalse(staleFile.exists());assertTrue(unknownFile.exists());assertTrue(recentFile.exists());assertTrue(link.exists());assertTrue(external.exists());assertTrue(activeFile.exists())
        } finally { StudioWorkJobs.finish(id,"active");listOf(stale,unknown,recent,linked).forEach{it.deleteRecursively()};external.delete() }
    }
    @Test fun composeProtectCompressCancellationDeletesOnlyGeneratedResults() {
        val original=source();val before=original.readBytes();val folder=File(context.cacheDir,"ops_${UUID.randomUUID()}").apply{mkdirs()}
        try {
            for(method in listOf("compose","protect","compress")) {
                var probes=0;val ops=StudioDocumentOps(context,folder) { if(++probes==3)throw CancellationException() }
                cancelled { when(method) {
                    "compose" -> ops.compose((0..2).map{mapOf("path" to original.path,"page" to it)})
                    "protect" -> ops.protect(original.path,"fixture-password")
                    else -> ops.compress(original.path,"small")
                };Unit }
                assertTrue("$method leaked a partial output",folder.listFiles()!!.isEmpty());assertArrayEquals(before,original.readBytes())
            }
        }finally{original.delete();folder.deleteRecursively()}
    }
    @Test fun flattenZipAndWordCancellationCloseResourcesAndRemovePartialFiles() {
        val original=source();val before=original.readBytes();val folder=File(context.cacheDir,"formats_${UUID.randomUUID()}").apply{mkdirs()}
        val formats=StudioExportFormats(context)
        try {
            for(method in listOf("flatten","zip","word","text")) {
                var probes=0;val probe={if(++probes==2)throw CancellationException();Unit}
                cancelled { when(method) {
                    "flatten" -> formats.compose((0..2).map{mapOf("path" to original.path,"page" to it)},probe,folder)
                    "zip" -> formats.pagesToImages(original.path,"png",probe,folder)
                    "word" -> formats.textToDocx("HYZEN pharmacy",probe,folder)
                    else -> formats.textToPdf("first\nsecond\nthird",probe,folder)
                };Unit }
                assertTrue("$method leaked output",folder.listFiles()!!.isEmpty());assertArrayEquals(before,original.readBytes())
                PDDocument.load(original).use{assertEquals(3,it.numberOfPages)}
            }
        }finally{original.delete();folder.deleteRecursively()}
    }
    @Test fun structuredPdfAndDocxCancelAfterWorkStartsWithoutLosingEditorInputs() {
        val folder=File(context.cacheDir,"writer_${UUID.randomUUID()}").apply{mkdirs()}
        val blocks=listOf(mapOf("type" to "paragraph","text" to "first block"),mapOf("type" to "table","text" to "A|B\nC|D"))
        try { for(format in listOf("pdf","docx")) {
            var probes=0
            cancelled { StudioRichWriter(context,folder) { if(++probes==3)throw CancellationException() }.write(blocks,format);Unit }
            assertTrue(folder.listFiles()!!.isEmpty());assertEquals("first block",blocks[0]["text"])
        }}finally{folder.deleteRecursively()}
    }
    @Test fun successfulSessionRetainsOutputUntilCommitAndDurableCopyAcknowledgement() {
        val client="success";val id=StudioWorkJobs.begin(client);val original=source();val folder=StudioWorkJobs.directory(context,id,client)
        var saved:File?=null
        try {
            StudioWorkJobs.start(id,client)
            val path=StudioDocumentOps(context,folder) { StudioWorkJobs.check(id,client) }.compose(listOf(mapOf("path" to original.path,"page" to 1)))
            StudioWorkJobs.end(id,client);assertTrue(File(path).isFile)
            assertTrue(StudioWorkJobs.commit(id,client));assertFalse(StudioWorkJobs.cancel(id,client));assertTrue(File(path).isFile)
            saved=File.createTempFile("durable_fixture_",".pdf",context.filesDir);File(path).copyTo(saved,true)
            assertTrue(StudioWorkJobs.finish(id,client));assertFalse(File(path).exists())
            PDDocument.load(saved).use{assertEquals(1,it.numberOfPages)};assertTrue(original.isFile)
        }finally{StudioWorkJobs.finish(id,client);original.delete();saved?.delete()}
    }
    @Test fun onlyUnstartedSessionsExpireWhileBetweenStepOutputRemainsOwned() {
        val client="expiry";val prepared=StudioWorkJobs.begin(client,0)
        val ready=StudioWorkJobs.begin(client,0)
        StudioWorkJobs.start(ready,client);StudioWorkJobs.end(ready,client)
        val next=StudioWorkJobs.begin("next",120001)
        try {
            rejected { StudioWorkJobs.start(prepared,client) }
            StudioWorkJobs.check(ready,client)
            StudioWorkJobs.start(ready,client);StudioWorkJobs.end(ready,client)
        }finally{StudioWorkJobs.finish(ready,client);StudioWorkJobs.finish(next,"next")}
    }
    @Test fun engineDetachAfterCommitRetainsOutputForRecoveryGracePeriod() {
        val client="detach-save";val id=StudioWorkJobs.begin(client)
        val folder=StudioWorkJobs.directory(context,id,client)
        val output=File(folder,"studio_copy.pdf").apply{writeText("fixture")}
        try {
            StudioWorkJobs.commit(id,client);StudioWorkJobs.abandon(client)
            assertTrue(output.exists());StudioWorkJobs.cleanup(context);assertTrue(output.exists())
            rejected { StudioWorkJobs.check(id,client) }
        }finally{output.delete();folder.delete()}
    }
    @Test fun ocrCancellationAfterPageRenderPreservesOriginalAndClosesRenderer() {
        val original=source();val before=original.readBytes()
        val folder=File(context.cacheDir,"ocr_${UUID.randomUUID()}").apply{mkdirs()}
        try {
            var probes=0
            cancelled { StudioDocumentOps(context,folder) { if(++probes==3)throw CancellationException() }.ocr(original.path);Unit }
            assertEquals(3,probes);assertTrue(folder.listFiles()!!.isEmpty());assertArrayEquals(before,original.readBytes())
            PDDocument.load(original).use{assertEquals(3,it.numberOfPages)}
        }finally{original.delete();folder.deleteRecursively()}
    }
}
